'use client';

import { useState } from 'react';
import { createClient } from '@/lib/supabase/client';
import Link from 'next/link';
import { Loader2 } from 'lucide-react';

export default function ForgotPasswordPage() {
  const [email, setEmail] = useState('');
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');
  const [success, setSuccess] = useState(false);
  const supabase = createClient();

  const handleForgotPassword = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);
    setError('');

    const { error } = await supabase.auth.resetPasswordForEmail(email, {
      redirectTo: `${window.location.origin}/update-password`,
    });

    if (error) {
      setError(error.message);
      setLoading(false);
    } else {
      setSuccess(true);
      setLoading(false);
    }
  };

  if (success) {
    return (
      <div className="min-h-[60vh] flex items-center justify-center px-4">
        <div className="w-full max-w-sm text-center space-y-4">
          <h1 className="text-2xl font-bold">Check your email</h1>
          <p className="text-muted-foreground">
            We've sent a password reset link to <strong>{email}</strong>.
            Please check your inbox (and spam folder) to continue.
          </p>
          <Link href="/login" className="inline-block text-primary hover:underline text-sm">
            Back to login
          </Link>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-[60vh] flex items-center justify-center px-4">
      <div className="w-full max-w-sm space-y-6">
        <div className="text-center">
          <h1 className="text-2xl font-bold">Forgot password?</h1>
          <p className="text-sm text-muted-foreground mt-1">
            Enter your email and we'll send you a reset link
          </p>
        </div>

        <form onSubmit={handleForgotPassword} className="space-y-4">
          <div>
            <label htmlFor="email" className="text-sm font-medium block mb-1">
              Email
            </label>
            <input
              id="email"
              type="email"
              value={email}
              onChange={(e) => setEmail(e.target.value)}
              placeholder="you@example.com"
              required
              className="w-full px-3 py-2 rounded-lg border border-border bg-background focus:outline-none focus:ring-2 focus:ring-primary/50"
            />
          </div>

          {error && (
            <p className="text-sm text-destructive bg-destructive/10 p-2 rounded-lg">
              {error}
            </p>
          )}

          <button
            type="submit"
            disabled={loading}
            className="w-full py-2 rounded-lg bg-primary text-primary-foreground font-medium hover:opacity-90 transition-all disabled:opacity-50 flex items-center justify-center gap-2"
          >
            {loading && <Loader2 className="h-4 w-4 animate-spin" />}
            Send reset link
          </button>
        </form>

        <p className="text-center text-sm text-muted-foreground">
          Remember your password?{' '}
          <Link href="/login" className="text-primary hover:underline">
            Sign in
          </Link>
        </p>
      </div>
    </div>
  );
}

'use client';

import { useState } from 'react';
import { createClient } from '@/lib/supabase/client';
import { useRouter } from 'next/navigation';
import Link from 'next/link';
import { Loader2 } from 'lucide-react';

export default function LoginPage() {
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');
  const [showForgotPassword, setShowForgotPassword] = useState(false);
  const router = useRouter();
  const supabase = createClient();

  const handleLogin = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);
    setError('');

    const { error } = await supabase.auth.signInWithPassword({ email, password });

    if (error) {
      setError(error.message);
      setLoading(false);
    } else {
      router.push('/');
      router.refresh();
    }
  };

  const handleOAuth = async (provider: 'google' | 'github') => {
    setLoading(true);
    setError('');
    const { error } = await supabase.auth.signInWithOAuth({ provider });
    if (error) {
      setError(error.message);
      setLoading(false);
    }
  };

  return (
    <div className="min-h-[60vh] flex items-center justify-center px-4">
      <div className="w-full max-w-sm space-y-6">
        <div className="text-center">
          <h1 className="text-2xl font-bold">Welcome back</h1>
          <p className="text-sm text-muted-foreground mt-1">Sign in to your account</p>
        </div>

        <form onSubmit={handleLogin} className="space-y-4">
          <div>
            <label htmlFor="email" className="text-sm font-medium block mb-1">Email</label>
            <input
              id="email"
              type="email"
              value={email}
              onChange={(e) => setEmail(e.target.value)}
              placeholder="you@example.com"
              required
              className="w-full px-3 py-2 rounded-lg border border-border bg-background focus:outline-none focus:ring-2 focus:ring-primary/50"
            />
          </div>
          <div>
            <label htmlFor="password" className="text-sm font-medium block mb-1">Password</label>
            <input
              id="password"
              type="password"
              value={password}
              onChange={(e) => setPassword(e.target.value)}
              placeholder="••••••••"
              required
              className="w-full px-3 py-2 rounded-lg border border-border bg-background focus:outline-none focus:ring-2 focus:ring-primary/50"
            />
          </div>

          {!showForgotPassword && (
            <p className="text-right">
              <Link
                href="/forgot-password"
                className="text-sm text-primary hover:underline"
              >
                Forgot password?
              </Link>
            </p>
          )}

          {error && (
            <p className="text-sm text-destructive bg-destructive/10 p-2 rounded-lg">{error}</p>
          )}

          <button
            type="submit"
            disabled={loading}
            className="w-full py-2 rounded-lg bg-primary text-primary-foreground font-medium hover:opacity-90 transition-all disabled:opacity-50 flex items-center justify-center gap-2"
          >
            {loading && <Loader2 className="h-4 w-4 animate-spin" />}
            Sign in
          </button>
        </form>

        <div className="relative">
          <div className="absolute inset-0 flex items-center"><span className="w-full border-t border-border" /></div>
          <div className="relative flex justify-center text-xs uppercase"><span className="bg-background px-2 text-muted-foreground">Or continue with</span></div>
        </div>

        <div className="grid grid-cols-2 gap-3">
          <button onClick={() => handleOAuth('google')} disabled={loading} className="py-2 rounded-lg border border-border hover:bg-accent transition-colors text-sm font-medium disabled:opacity-50">
            Google
          </button>
          <button onClick={() => handleOAuth('github')} disabled={loading} className="py-2 rounded-lg border border-border hover:bg-accent transition-colors text-sm font-medium disabled:opacity-50">
            GitHub
          </button>
        </div>

        <p className="text-center text-sm text-muted-foreground">
          Don&apos;t have an account?{' '}
          <Link href="/register" className="text-primary hover:underline">Sign up</Link>
        </p>
      </div>
    </div>
  );
}

'use client';

import { useState, useEffect } from 'react';
import { createClient } from '@/lib/supabase/client';
import { useRouter, useSearchParams } from 'next/navigation';
import Link from 'next/link';
import { Loader2 } from 'lucide-react';

function UpdatePasswordForm() {
  const [password, setPassword] = useState('');
  const [confirmPassword, setConfirmPassword] = useState('');
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');
  const [success, setSuccess] = useState(false);
  const [validToken, setValidToken] = useState(false);
  const router = useRouter();
  const searchParams = useSearchParams();
  const supabase = createClient();

  useEffect(() => {
    // Verify the token is present in the URL
    const token = searchParams.get('code') || searchParams.get('access_token');
    const type = searchParams.get('type');

    if (token && type === 'recovery') {
      setValidToken(true);
    } else {
      setValidToken(false);
      setError('Invalid or expired reset link. Please request a new one.');
    }
  }, [searchParams]);

  const handleUpdatePassword = async (e: React.FormEvent) => {
    e.preventDefault();
    setError('');

    if (password !== confirmPassword) {
      setError('Passwords do not match');
      return;
    }

    if (password.length < 6) {
      setError('Password must be at least 6 characters');
      return;
    }

    setLoading(true);

    const { error } = await supabase.auth.updateUser({ password });

    if (error) {
      setError(error.message);
      setLoading(false);
    } else {
      setSuccess(true);
      setLoading(false);
    }
  };

  if (!validToken) {
    return (
      <div className="min-h-[60vh] flex items-center justify-center px-4">
        <div className="w-full max-w-sm text-center space-y-4">
          <h1 className="text-2xl font-bold">Invalid reset link</h1>
          <p className="text-muted-foreground">
            This password reset link is invalid or has expired.
          </p>
          <Link
            href="/forgot-password"
            className="inline-block text-primary hover:underline text-sm"
          >
            Request a new link
          </Link>
        </div>
      </div>
    );
  }

  if (success) {
    return (
      <div className="min-h-[60vh] flex items-center justify-center px-4">
        <div className="w-full max-w-sm text-center space-y-4">
          <h1 className="text-2xl font-bold">Password updated</h1>
          <p className="text-muted-foreground">
            Your password has been successfully reset.
          </p>
          <Link href="/login" className="inline-block text-primary hover:underline text-sm">
            Sign in
          </Link>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-[60vh] flex items-center justify-center px-4">
      <div className="w-full max-w-sm space-y-6">
        <div className="text-center">
          <h1 className="text-2xl font-bold">Set new password</h1>
          <p className="text-sm text-muted-foreground mt-1">
            Enter your new password below
          </p>
        </div>

        <form onSubmit={handleUpdatePassword} className="space-y-4">
          <div>
            <label htmlFor="password" className="text-sm font-medium block mb-1">
              New Password
            </label>
            <input
              id="password"
              type="password"
              value={password}
              onChange={(e) => setPassword(e.target.value)}
              placeholder="At least 6 characters"
              required
              minLength={6}
              autoComplete="new-password"
              className="w-full px-3 py-2 rounded-lg border border-border bg-background focus:outline-none focus:ring-2 focus:ring-primary/50"
            />
          </div>
          <div>
            <label
              htmlFor="confirmPassword"
              className="text-sm font-medium block mb-1"
            >
              Confirm New Password
            </label>
            <input
              id="confirmPassword"
              type="password"
              value={confirmPassword}
              onChange={(e) => setConfirmPassword(e.target.value)}
              placeholder="••••••••"
              required
              minLength={6}
              autoComplete="new-password"
              className="w-full px-3 py-2 rounded-lg border border-border bg-background focus:outline-none focus:ring-2 focus:ring-primary/50"
            />
          </div>

          {error && (
            <p className="text-sm text-destructive bg-destructive/10 p-2 rounded-lg">
              {error}
            </p>
          )}

          <button
            type="submit"
            disabled={loading}
            className="w-full py-2 rounded-lg bg-primary text-primary-foreground font-medium hover:opacity-90 transition-all disabled:opacity-50 flex items-center justify-center gap-2"
          >
            {loading && <Loader2 className="h-4 w-4 animate-spin" />}
            Update password
          </button>
        </form>

        <p className="text-center text-sm text-muted-foreground">
          <Link href="/login" className="text-primary hover:underline">
            Back to login
          </Link>
        </p>
      </div>
    </div>
  );
}

import { Suspense } from 'react';

export default function UpdatePasswordPage() {
  return (
    <Suspense fallback={<div className="min-h-[60vh] flex items-center justify-center px-4">Loading...</div>}>
      <UpdatePasswordForm />
    </Suspense>
  );
}

import { NextResponse } from 'next/server';
import { createClient } from '@supabase/supabase-js';
import { rescoreArticles } from '@/lib/pipeline/rank';
import type { ArticleForRescoring } from '@/lib/pipeline/rank';

// ─── Config ────────────────────────────────────────────────

export const dynamic = 'force-dynamic';
export const revalidate = 0;

const LOOKBACK_HOURS = 72;
const BATCH_SIZE = 100;

// ─── Lazy Supabase client ─────────────────────────────────

let _sb: ReturnType<typeof createClient> | null = null;

function getClient(): ReturnType<typeof createClient> | null {
  if (_sb) return _sb;
  const url = process.env.NEXT_PUBLIC_SUPABASE_URL;
  const key = process.env.SUPABASE_SERVICE_ROLE_KEY || process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY;
  if (!url || !key) return null;
  _sb = createClient(url, key, { auth: { persistSession: false } });
  return _sb;
}

// ─── Route Handlers ────────────────────────────────────────

/**
 * GET: Health check / current config info
 */
export async function GET() {
  return NextResponse.json({
    status: 'ready',
    message: 'POST to trigger article rescore',
    lookback_hours: LOOKBACK_HOURS,
    batch_size: BATCH_SIZE,
  });
}

/**
 * POST: Trigger full rescore of recent articles.
 * Protected by Vercel Cron secret (set CRON_SECRET env var).
 */
export async function POST(request: Request) {
  // Verify cron secret
  const authHeader = request.headers.get('authorization');
  const expectedSecret = process.env.CRON_SECRET;
  if (expectedSecret && authHeader !== `Bearer ${expectedSecret}`) {
    return NextResponse.json({ error: 'Unauthorized' }, { status: 401 });
  }

  const startTime = Date.now();
  const client = getClient();

  if (!client) {
    return NextResponse.json(
      { success: false, error: 'Supabase client not configured' },
      { status: 500 }
    );
  }

  try {
    // 1. Fetch articles from last LOOKBACK_HOURS
    const lookbackDate = new Date(
      Date.now() - LOOKBACK_HOURS * 60 * 60 * 1000
    ).toISOString();

    const { data: articles, error: fetchError } = await client
      .from('articles')
      .select(
        'id, title, summary, score, base_score, social_momentum, published_at, category, source_name, source_type, detected_models'
      )
      .gte('published_at', lookbackDate)
      .order('published_at', { ascending: false })
      .limit(5000);

    if (fetchError) {
      throw new Error(`Fetch error: ${fetchError.message}`);
    }

    if (!articles || articles.length === 0) {
      return NextResponse.json({
        success: true,
        total_articles: 0,
        total_updated: 0,
        total_duration_ms: Date.now() - startTime,
        message: 'No articles to rescore',
      });
    }

    // 2. Map to pipeline input type
    const articlesToRescore: ArticleForRescoring[] = articles.map(
      (a: Record<string, unknown>) => ({
        id: a.id as string,
        title: (a.title as string) ?? '',
        summary: (a.summary as string) ?? null,
        score: (a.score as number) ?? 0,
        base_score: (a.base_score as number | null) ?? null,
        social_momentum: (a.social_momentum as number | null) ?? null,
        published_at: (a.published_at as string) ?? null,
        category: (a.category as string) ?? null,
        source_name: (a.source_name as string) ?? '',
        source_type: (a.source_type as string) ?? 'rss',
        detected_models: (a.detected_models as string[] | null) ?? null,
      })
    );

    // 3. Rescore in batches
    const allResults: Array<{
      articleId: string;
      newScore: number;
      trendingScore: number;
      socialMomentum: number;
    }> = [];

    for (let i = 0; i < articlesToRescore.length; i += BATCH_SIZE) {
      const batch = articlesToRescore.slice(i, i + BATCH_SIZE);
      const results = await rescoreArticles(batch);

      // Build update payloads
      const updates = results.map((r) => ({
        id: r.articleId,
        score: r.newScore,
        social_momentum: r.socialMomentum,
        updated_at: new Date().toISOString(),
      }));

      // Batch update in Supabase
      // eslint-disable-next-line @typescript-eslint/no-explicit-any
      const sba = client.from('articles') as any;
      const { error: updateError } = await sba
        .upsert(updates as any[], { onConflict: 'id' });

      if (updateError) {
        console.error(
          `[Rescore Cron] Batch update error (batch ${i}):`,
          updateError.message
        );
      }

      allResults.push(
        ...results.map((r) => ({
          articleId: r.articleId,
          newScore: r.newScore,
          trendingScore: r.trendingScore,
          socialMomentum: r.socialMomentum,
        }))
      );

      // Small delay between batches to avoid overwhelming the DB
      if (i + BATCH_SIZE < articlesToRescore.length) {
        await new Promise((resolve) => setTimeout(resolve, 100));
      }
    }

    // 4. Summary stats
    const avgScoreChange =
      allResults.reduce(
        (sum, r) => sum + r.newScore,
        0
      ) / allResults.length;

    const totalUpdated = allResults.length;

    return NextResponse.json({
      success: true,
      total_articles: articles.length,
      total_updated: totalUpdated,
      average_new_score: Math.round(avgScoreChange * 10) / 10,
      lookback_hours: LOOKBACK_HOURS,
      total_duration_ms: Date.now() - startTime,
    });
  } catch (error) {
    console.error('[Rescore Cron] Fatal:', error);
    return NextResponse.json(
      {
        success: false,
        total_duration_ms: Date.now() - startTime,
        error: error instanceof Error ? error.message : 'Unknown',
      },
      { status: 500 }
    );
  }
}

import { NextResponse } from 'next/server';
import { createClient } from '@supabase/supabase-js';

export const dynamic = 'force-dynamic';
export const maxDuration = 30;

/**
 * GET /api/daily-feed?cursor={date}&limit=50
 *
 * Returns articles grouped by date (day buckets), newest first.
 * - No tabs, just chronological by published_at DESC
 * - Cursor = date string (YYYY-MM-DD) of the LAST day fully loaded
 *   When cursor provided, returns days STRICTLY OLDER than that date
 * - Max 7 days back (configurable)
 * - Returns: { days: [{ date, label, articles: [] }], hasMore, nextCursor }
 */
export async function GET(request: Request) {
  const url = new URL(request.url);
  const limit = Math.min(Math.max(parseInt(url.searchParams.get('limit') || '50', 10) || 50, 10), 200);
  const cursor = url.searchParams.get('cursor'); // YYYY-MM-DD of last loaded day
  const maxDays = 7;

  const supabaseUrl = process.env.NEXT_PUBLIC_SUPABASE_URL || process.env.SUPABASE_URL;
  const supabaseKey = process.env.SUPABASE_SERVICE_ROLE_KEY || process.env.SUPABASE_KEY;

  if (!supabaseUrl || !supabaseKey) {
    return NextResponse.json({ error: 'Supabase not configured' }, { status: 500 });
  }

  const supabase = createClient(supabaseUrl, supabaseKey);

  // Build the base query: published articles from last 7 days
  const sevenDaysAgo = new Date(Date.now() - maxDays * 24 * 60 * 60 * 1000).toISOString();
  const now = new Date().toISOString();

  let query = supabase
    .from('articles')
    .select('id, title, summary, image_url, source_name, category, tags, published_at, score, is_breaking, content, language')
    .eq('status', 'published')
    .gte('published_at', sevenDaysAgo)
    .lte('published_at', now)  // Exclude future-dated articles
    .order('published_at', { ascending: false })
    .limit(limit * maxDays + 1); // fetch enough to cover all days

  const { data, error } = await query;

  if (error) {
    console.error('API /api/daily-feed error:', error);
    return NextResponse.json({ error: 'Failed to fetch articles' }, { status: 500 });
  }

  const allArticles = (data || []) as Array<{
    id: string;
    title: string;
    summary: string | null;
    image_url: string | null;
    source_name: string;
    category: string | null;
    tags: string[];
    published_at: string;
    score: number;
    is_breaking: boolean;
    content: string | null;
    language: string | null;
  }>;

  // Group by date (YYYY-MM-DD) in user's local time (UTC for now, can be improved)
  const groups = new Map<string, typeof allArticles>();
  for (const article of allArticles) {
    const date = article.published_at.split('T')[0]; // YYYY-MM-DD
    if (!groups.has(date)) groups.set(date, []);
    groups.get(date)!.push(article);
  }

  // Sort dates descending (newest first)
  const sortedDates = Array.from(groups.keys()).sort((a, b) => b.localeCompare(a));

  // Apply cursor: only include days STRICTLY OLDER than cursor
  let startIdx = 0;
  if (cursor) {
    const cursorIdx = sortedDates.indexOf(cursor);
    if (cursorIdx >= 0) {
      startIdx = cursorIdx + 1; // skip cursor day and newer
    }
  }

  // Take up to maxDays from startIdx
  const selectedDates = sortedDates.slice(startIdx, startIdx + maxDays);

  // Build day objects with formatted labels
  const days = selectedDates.map((date) => {
    const articles = groups.get(date)!;
    // Sort articles within day: score desc, then published_at desc
    articles.sort((a, b) => b.score - a.score || b.published_at.localeCompare(a.published_at));

    // Format label: "Today", "Yesterday", "Monday June 8", etc.
    const articleDate = new Date(date + 'T00:00:00');
    const today = new Date();
    today.setHours(0, 0, 0, 0);
    const yesterday = new Date(today);
    yesterday.setDate(yesterday.getDate() - 1);

    let label: string;
    if (articleDate.getTime() === today.getTime()) {
      label = "Today";
    } else if (articleDate.getTime() === yesterday.getTime()) {
      label = "Yesterday";
    } else {
      label = articleDate.toLocaleDateString('en-US', {
        weekday: 'long',
        month: 'long',
        day: 'numeric',
      });
    }

    return { date, label, articles };
  });

  const hasMore = startIdx + selectedDates.length < sortedDates.length;
  const nextCursor = hasMore ? sortedDates[startIdx + selectedDates.length - 1] : null;

  return NextResponse.json({
    days,
    hasMore,
    nextCursor,
    totalDays: sortedDates.length,
    loadedDays: days.length,
  });
}

import { NextResponse } from 'next/server';
import { createAdminClient } from '@/lib/supabase/server';
import type { SupabaseClient } from '@supabase/supabase-js';

export const dynamic = 'force-dynamic';
export const maxDuration = 30;

interface PersonalizedArticle {
  id: string;
  title: string;
  summary: string | null;
  url: string;
  source_name: string;
  source_type: string;
  source_tier: number | null;
  category: string | null;
  published_at: string;
  score: number;
  base_score: number | null;
  social_momentum: number | null;
  detected_models: string[] | null;
  image_url: string | null;
  slug: string;
  relevance_score: number;
  reason: string;
}

async function getUserEmbeddings(supabase: SupabaseClient, userId: string): Promise<number[] | null> {
  const { data } = await supabase
    .from('user_embeddings')
    .select('embedding')
    .eq('user_id', userId)
    .single();
  return data?.embedding ?? null;
}

async function getUserClickHistory(supabase: SupabaseClient, userId: string, limit = 50): Promise<string[]> {
  const { data } = await supabase
    .from('article_clicks')
    .select('article_id')
    .eq('user_id', userId)
    .order('created_at', { ascending: false })
    .limit(limit);
  return data?.map((d) => d.article_id) ?? [];
}

async function getUserBookmarks(supabase: SupabaseClient, userId: string, limit = 100): Promise<string[]> {
  const { data } = await supabase
    .from('bookmarks')
    .select('article_id')
    .eq('user_id', userId)
    .order('created_at', { ascending: false })
    .limit(limit);
  return data?.map((d) => d.article_id) ?? [];
}

async function getCategoryPreferences(supabase: SupabaseClient, userId: string): Promise<Record<string, number>> {
  const { data } = await supabase
    .from('user_category_preferences')
    .select('category, weight')
    .eq('user_id', userId);
  return Object.fromEntries(data?.map((d) => [d.category, d.weight]) ?? []);
}

async function getCandidateArticles(
  supabase: SupabaseClient,
  options: {
    excludeIds: string[];
    limit: number;
    categories?: string[];
    hoursBack: number;
  }
): Promise<PersonalizedArticle[]> {
  const lookbackDate = new Date(Date.now() - options.hoursBack * 60 * 60 * 1000).toISOString();

  let query = supabase
    .from('articles')
    .select(
      'id, title, summary, url, source_name, source_type, source_tier, category, published_at, score, base_score, social_momentum, detected_models, image_url, slug'
    )
    .gte('published_at', lookbackDate)
    .order('published_at', { ascending: false })
    .limit(options.limit * 3);

  if (options.categories && options.categories.length > 0) {
    query = query.in('category', options.categories);
  }

  if (options.excludeIds.length > 0) {
    query = query.not('id', 'in', `(${options.excludeIds.join(',')})`);
  }

  const { data, error } = await query;

  if (error) {
    console.error('[ForYou API] Error fetching candidates:', error.message);
    return [];
  }

  return (data ?? []) as PersonalizedArticle[];
}

function calculateRelevanceScore(
  article: PersonalizedArticle,
  context: {
    userEmbedding: number[] | null;
    clickedIds: Set<string>;
    bookmarkedIds: Set<string>;
    categoryPrefs: Record<string, number>;
    articleEmbeddings: Map<string, number[]>;
  }
): { score: number; reason: string } {
  let score = 0;
  const reasons: string[] = [];

  if (article.category && context.categoryPrefs[article.category]) {
    score += context.categoryPrefs[article.category] * 0.3;
    reasons.push(`category:${article.category}`);
  }

  if (context.userEmbedding && context.articleEmbeddings.has(article.id)) {
    const articleEmb = context.articleEmbeddings.get(article.id)!;
    const similarity = cosineSimilarity(context.userEmbedding, articleEmb);
    if (similarity > 0.7) {
      score += similarity * 0.4;
      reasons.push(`similar_to_history:${(similarity * 100).toFixed(0)}%`);
    }
  }

  const hoursAgo = Math.max(0, (Date.now() - new Date(article.published_at).getTime()) / 3_600_000);
  if (hoursAgo < 24) {
    score += 0.1 * (1 - hoursAgo / 24);
    reasons.push('recent');
  }

  if (article.source_tier && article.source_tier <= 2) {
    score += 0.05 * (3 - article.source_tier);
    reasons.push('quality_source');
  }

  score += (article.score ?? 50) / 100 * 0.2;

  const reason = reasons.join(' + ') || 'discovery';
  return { score: Math.min(1, Math.max(0, score)), reason };
}

function cosineSimilarity(a: number[], b: number[]): number {
  if (a.length !== b.length) return 0;
  let dot = 0, normA = 0, normB = 0;
  for (let i = 0; i < a.length; i++) {
    dot += a[i] * b[i];
    normA += a[i] * a[i];
    normB += b[i] * b[i];
  }
  if (normA === 0 || normB === 0) return 0;
  return dot / (Math.sqrt(normA) * Math.sqrt(normB));
}

async function fetchArticleEmbeddings(
  supabase: SupabaseClient,
  articleIds: string[]
): Promise<Map<string, number[]>> {
  if (articleIds.length === 0) return new Map();

  const { data } = await supabase
    .from('article_embeddings')
    .select('article_id, embedding')
    .in('article_id', articleIds);

  const map = new Map<string, number[]>();
  data?.forEach((d) => map.set(d.article_id, d.embedding));
  return map;
}

async function getTrendingFallback(
  supabase: SupabaseClient,
  limit: number,
  hoursBack: number
) {
  const lookbackDate = new Date(Date.now() - hoursBack * 60 * 60 * 1000).toISOString();

  const { data, error } = await supabase
    .from('articles')
    .select(
      'id, title, summary, url, source_name, source_type, source_tier, category, published_at, score, base_score, social_momentum, detected_models, image_url, slug'
    )
    .gte('published_at', lookbackDate)
    .order('score', { ascending: false })
    .limit(limit);

  if (error || !data) {
    return NextResponse.json({ articles: [], next_cursor: null, has_more: false, personalized: false });
  }

  return NextResponse.json({
    articles: data as PersonalizedArticle[],
    next_cursor: null,
    has_more: false,
    personalized: false,
  });
}

export async function GET(request: Request) {
  const { searchParams } = new URL(request.url);
  const limit = Math.min(parseInt(searchParams.get('limit') || '20'), 50);
  const hoursBack = Math.min(parseInt(searchParams.get('hours_back') || '168'), 720);
  const cursor = searchParams.get('cursor');

  const supabase = await createAdminClient();
  const { data: { user } } = await supabase.auth.getUser();

  if (!user) {
    return getTrendingFallback(supabase, limit, hoursBack);
  }

  try {
    const [userEmbedding, clickedIds, bookmarkedIds, categoryPrefs] = await Promise.all([
      getUserEmbeddings(supabase, user.id),
      getUserClickHistory(supabase, user.id),
      getUserBookmarks(supabase, user.id),
      getCategoryPreferences(supabase, user.id),
    ]);

    const clickedSet = new Set(clickedIds);
    const bookmarkedSet = new Set(bookmarkedIds);
    const excludeIds = [...clickedIds, ...bookmarkedIds];

    const categories = Object.keys(categoryPrefs).length > 0 ? Object.keys(categoryPrefs) : undefined;
    const candidates = await getCandidateArticles(supabase, {
      excludeIds,
      limit: 100,
      categories,
      hoursBack,
    });

    if (candidates.length === 0) {
      return getTrendingFallback(supabase, limit, hoursBack);
    }

    const candidateIds = candidates.map((a) => a.id);
    const articleEmbeddings = await fetchArticleEmbeddings(supabase, candidateIds);

    const ranked = candidates
      .map((article) => {
        const { score, reason } = calculateRelevanceScore(article, {
          userEmbedding,
          clickedIds: clickedSet,
          bookmarkedIds: bookmarkedSet,
          categoryPrefs,
          articleEmbeddings,
        });
        return { ...article, relevance_score: score, reason };
      })
      .sort((a, b) => b.relevance_score - a.relevance_score)
      .slice(0, limit);

    const nextCursor = ranked.length === limit ? ranked[ranked.length - 1].id : null;

    await supabase.from('recommendation_logs').insert({
      user_id: user.id,
      article_ids: ranked.map((a) => a.id),
      algorithm: 'hybrid_v1',
      created_at: new Date().toISOString(),
    });

    return NextResponse.json({
      articles: ranked,
      next_cursor: nextCursor,
      has_more: nextCursor !== null,
      personalized: true,
    });
  } catch (error) {
    console.error('[ForYou API] Error:', error);
    return getTrendingFallback(supabase, limit, hoursBack);
  }
}

import { NextResponse } from 'next/server';

export const dynamic = 'force-dynamic';
export const maxDuration = 30;

const CACHE_TTL = 15 * 60 * 1000; // 15 minutes
let cache: { data: any[]; timestamp: number } | null = null;

interface HFModel {
  id: string;
  author: string;
  name: string;
  task: string;
  downloads: number;
  likes: number;
  params: string;
  updated: string;
  link: string;
}

/**
 * GET /api/huggingface/trending?limit=10
 *
 * Returns top trending models from Hugging Face.
 * Fetches from HF API sorted by recently updated models so the widget does not
 * show stale all-time download leaders as “trending”.
 */
export async function GET(request: Request) {
  const url = new URL(request.url);
  const limit = Math.min(Math.max(parseInt(url.searchParams.get('limit') || '10', 10) || 10, 1), 25);

  // Return from cache if fresh
  if (cache && Date.now() - cache.timestamp < CACHE_TTL) {
    return NextResponse.json({ models: cache.data.slice(0, limit), cached: true });
  }

  try {
    // Fetch recently updated/high-signal models from HF API. Sorting by all-time
    // downloads returns stale 2022-era sentence-transformer rows, not trends.
    const res = await fetch(
      'https://huggingface.co/api/models?sort=lastModified&direction=-1&limit=50',
      { headers: { 'User-Agent': 'DailyAI/1.0' }, signal: AbortSignal.timeout(10000) }
    );

    if (!res.ok) throw new Error(`HF API error: ${res.status}`);

    const data = await res.json();

    if (!Array.isArray(data) || data.length === 0) {
      return NextResponse.json({ models: [], cached: false });
    }

    // Filter out low-quality models (private, spammy, 0 downloads)
    const models: HFModel[] = data
      .filter((m: any) => !m.private && (m.likes > 0 || m.downloads > 100))
      .slice(0, limit)
      .map((m: any) => {
        const fullId = m.id || m.modelId || '';
        const parts = fullId.split('/');
        const author = parts[0] || '';
        const name = parts.slice(1).join('/') || fullId;

        // Extract model params from tags or description
        const paramTag = (m.tags || []).find((t: string) => /^\d+[.]?\d*[BMK]?$/.test(t));
        const params = paramTag || '';

        return {
          id: fullId,
          author,
          name,
          task: m.pipeline_tag || m.library_name || '',
          downloads: m.downloads || 0,
          likes: m.likes || 0,
          params,
          updated: m.lastModified || m.createdAt || '',
          link: `https://huggingface.co/${fullId}`,
        };
      });

    cache = { data: models, timestamp: Date.now() };

    return NextResponse.json({ models, cached: false });
  } catch (err) {
    console.error('[HF API] Error:', err);

    // Fall back to cache even if stale
    if (cache) {
      return NextResponse.json({ models: cache.data.slice(0, limit), cached: true, stale: true });
    }

    return NextResponse.json({ models: [], cached: false, error: 'Failed to fetch' });
  }
}

import { NextResponse } from 'next/server';
import { createClient } from '@supabase/supabase-js';

export const dynamic = 'force-dynamic';
export const maxDuration = 30;

const MODEL_NAME_PATTERNS = [
  // Claude series
  { regex: /Claude\s*(?:3\.5|4\.\d+|4|Opus|Sonnet|Haiku)/gi, name: null },
  // GPT series
  { regex: /GPT[-_]?(?:4[ot]?|5|4\.\d+|o[123]?|mini|turbo)/gi, name: null },
  // Gemini series
  { regex: /Gemini\s*(?:2\.\d+|Ultra|Pro|Flash|Nano|Exp)/gi, name: null },
  // DeepSeek series
  { regex: /DeepSeek[-_ ]?(?:R1|V3|R2|VL2?|Coder|Pro|V2\.\d+)/gi, name: null },
  // Qwen series
  { regex: /Qwen[23]?(?:[-_])?(?:\d+[.]?\d*B)?(?:\s*[-\/]\s*[A-Za-z0-9]+)?/gi, name: null },
  // Llama series
  { regex: /Llama\s*(?:3\.\d+|4\.\d+|2\.\d+)?/gi, name: null },
  // Mistral series
  { regex: /Mistral\s*(?:Large|Small|Nemo|Saba|7B|8x22B|NeMo|3\.\d+)?/gi, name: null },
  // Phi series
  { regex: /Phi[-_]?(?:3\.\d+|4|mini|vision|silica|moE)?/gi, name: null },
  // Grok series
  { regex: /Grok[-_ ]?(?:3|2|1\.\d+)?/gi, name: null },
  // Stable Diffusion
  { regex: /Stable\s*Diffusion\s*(?:3[.]?\d+|4[.]?\d+|XL|Turbo)?/gi, name: null },
  // General model patterns (catch-all for new versions)
  { regex: /(?:\w+[-_])?(?:\d+[.]?\d*[Bb])(?:[-_]\w+)?/gi, name: null },
];

function extractModelNames(title: string, summary: string | null, tags: string[]): string[] {
  const text = `${title} ${summary || ''} ${tags.join(' ')}`;
  const found = new Set<string>();

  for (const { regex } of MODEL_NAME_PATTERNS) {
    let m;
    while ((m = regex.exec(text)) !== null) {
      found.add(m[0].trim());
    }
  }

  return Array.from(found);
}

/**
 * GET /api/news/models?limit=10
 *
 * Returns latest AI model mentions extracted from real articles.
 * Queries articles with category='models' or entities containing model type.
 */
export async function GET(request: Request) {
  const url = new URL(request.url);
  const limit = Math.min(Math.max(parseInt(url.searchParams.get('limit') || '10', 10) || 10, 1), 30);

  const supabaseUrl = process.env.NEXT_PUBLIC_SUPABASE_URL || process.env.SUPABASE_URL;
  const supabaseKey = process.env.SUPABASE_SERVICE_ROLE_KEY || process.env.SUPABASE_KEY;

  if (!supabaseUrl || !supabaseKey) {
    return NextResponse.json({ error: 'Supabase not configured' }, { status: 500 });
  }

  const supabase = createClient(supabaseUrl, supabaseKey);

  // Fetch recent articles about models (category or entities containing model type)
  const { data, error } = await supabase
    .from('articles')
    .select('id, title, summary, source_name, category, tags, entities, published_at, score')
    .eq('status', 'published')
    .eq('category', 'models')
    .gte('published_at', new Date(Date.now() - 14 * 24 * 60 * 60 * 1000).toISOString()) // last 14 days
    .order('published_at', { ascending: false })
    .limit(limit * 3); // fetch extra for dedup

  if (error) {
    console.error('API /api/news/models error:', error);
    return NextResponse.json({ error: 'Failed to fetch models' }, { status: 500 });
  }

  // Build model entries: deduplicate by model name, keep the most recent article
  const modelMap = new Map<string, {
    name: string;
    articleId: string;
    articleTitle: string;
    sourceName: string;
    publishedAt: string;
    score: number;
    link: string;
  }>();

  for (const article of (data || [])) {
    const modelNames = extractModelNames(article.title, article.summary, article.tags || []);

    // Also extract from entities
    let entityModels: string[] = [];
    try {
      const entities = typeof article.entities === 'string'
        ? JSON.parse(article.entities)
        : article.entities || [];
      entityModels = entities
        .filter((e: any) => e.type === 'model')
        .map((e: any) => e.name);
    } catch {}

    const allNames = [...new Set([...modelNames, ...entityModels])];

    for (const name of allNames) {
      const key = name.toLowerCase().replace(/[\s_-]+/g, '');
      if (!modelMap.has(key)) {
        modelMap.set(key, {
          name: name.replace(/\b(\w)/g, (c) => c.toUpperCase()),
          articleId: article.id,
          articleTitle: article.title,
          sourceName: article.source_name,
          publishedAt: article.published_at,
          score: article.score || 0,
          link: `/article/${article.id}`,
        });
      }
    }
  }

  // Sort by published date (newest first), take top N
  const models = Array.from(modelMap.values())
    .sort((a, b) => new Date(b.publishedAt).getTime() - new Date(a.publishedAt).getTime())
    .slice(0, limit);

  return NextResponse.json({
    models,
    total: models.length,
    cached: false,
  });
}

import { NextRequest, NextResponse } from 'next/server';
import { createAdminClient } from '@/lib/supabase/server';
import { resend } from '@/lib/resend';
import { format } from 'date-fns';

export async function POST(request: NextRequest) {
  try {
    // Verify cron secret
    const authHeader = request.headers.get('authorization');
    const cronSecret = process.env.CRON_SECRET;
    if (cronSecret && authHeader !== `Bearer ${cronSecret}`) {
      return NextResponse.json({ error: 'Unauthorized' }, { status: 401 });
    }

    const body = await request.json().catch(() => ({}));
    const frequency = body.frequency || 'daily'; // 'daily' or 'weekly'

    const supabase = await createAdminClient();

    // Get time range
    const now = new Date();
    const startDate = new Date(now);
    if (frequency === 'daily') {
      startDate.setDate(startDate.getDate() - 1);
    } else {
      startDate.setDate(startDate.getDate() - 7);
    }

    // Fetch confirmed subscriptions for this frequency
    const { data: subscriptions, error: subError } = await supabase
      .from('newsletter_subscriptions')
      .select('email, preferences')
      .eq('frequency', frequency)
      .eq('confirmed', true);

    if (subError) {
      console.error('Fetch subscriptions error:', subError);
      return NextResponse.json({ error: 'Failed to fetch subscriptions' }, { status: 500 });
    }

    if (!subscriptions || subscriptions.length === 0) {
      return NextResponse.json({ success: true, sent: 0, message: 'No subscribers' });
    }

    // Fetch articles for the period
    const { data: articles, error: articlesError } = await supabase
      .from('articles')
      .select('id, title, summary, url, source, published_at, category, entities')
      .gte('published_at', startDate.toISOString())
      .lte('published_at', now.toISOString())
      .order('published_at', { ascending: false })
      .limit(50);

    if (articlesError) {
      console.error('Fetch articles error:', articlesError);
      return NextResponse.json({ error: 'Failed to fetch articles' }, { status: 500 });
    }

    // Group articles by category
    const articlesByCategory = (articles || []).reduce((acc, article) => {
      const cat = article.category || 'General';
      if (!acc[cat]) acc[cat] = [];
      acc[cat].push(article);
      return acc;
    }, {} as Record<string, typeof articles>);

    // Generate HTML email
    const dateStr = format(now, 'EEEE, MMMM d, yyyy');
    const html = generateNewsletterHTML(articlesByCategory, dateStr, frequency);

    // Send to all subscribers
    if (!resend) {
      console.warn('Resend not configured, skipping email send');
      return NextResponse.json({ success: true, sent: 0, message: 'Resend not configured' });
    }

    const emails = subscriptions.map((s) => ({
      from: 'Nous AI News <newsletter@nous-daily.vercel.app>',
      to: [s.email],
      subject: `${frequency === 'daily' ? 'Daily' : 'Weekly'} AI News Digest — ${dateStr}`,
      html,
    }));

    // Send in batches (Resend limit)
    const batchSize = 50;
    let sent = 0;
    for (let i = 0; i < emails.length; i += batchSize) {
      const batch = emails.slice(i, i + batchSize);
      await Promise.all(batch.map((email) => resend!.emails.send(email)));
      sent += batch.length;
    }

    return NextResponse.json({ success: true, sent, frequency, date: dateStr });
  } catch (error) {
    console.error('Newsletter send error:', error);
    return NextResponse.json({ error: 'Internal server error' }, { status: 500 });
  }
}

function generateNewsletterHTML(
  articlesByCategory: Record<string, any[]>,
  dateStr: string,
  frequency: string
): string {
  const categories = Object.entries(articlesByCategory);

  let categoryHtml = '';
  for (const [cat, articles] of categories) {
    categoryHtml += `
      <h2 style="color: #8b5cf6; margin-top: 32px; margin-bottom: 16px; font-size: 18px; border-bottom: 2px solid #8b5cf6; padding-bottom: 8px;">
        ${cat} (${articles.length})
      </h2>
    `;

    for (const article of articles.slice(0, 10)) {
      categoryHtml += `
        <div style="margin-bottom: 20px; padding: 16px; background: #1e1e1e; border-radius: 8px; border: 1px solid #333;">
          <h3 style="margin: 0 0 8px 0; font-size: 15px; font-weight: 600;">
            <a href="${article.url}" style="color: #fff; text-decoration: none;">${article.title}</a>
          </h3>
          <p style="margin: 8px 0 0 0; color: #aaa; font-size: 13px; line-height: 1.5;">${article.summary || ''}</p>
          <div style="margin-top: 8px; font-size: 12px; color: #666;">
            ${article.source} • ${new Date(article.published_at).toLocaleDateString()}
          </div>
        </div>
      `;
    }
  }

  return `
    <!DOCTYPE html>
    <html>
    <head>
      <meta charset="utf-8">
      <meta name="viewport" content="width=device-width, initial-scale=1.0">
    </head>
    <body style="margin: 0; padding: 0; font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif; background: #0a0a0a; color: #fff;">
      <div style="max-width: 600px; margin: 0 auto; padding: 20px;">
        <!-- Header -->
        <div style="text-align: center; padding: 24px 0; border-bottom: 1px solid #333;">
          <h1 style="margin: 0; font-size: 24px; background: linear-gradient(135deg, #8b5cf6, #a855f7); -webkit-background-clip: text; -webkit-text-fill-color: transparent;">
            Nous AI News
          </h1>
          <p style="margin: 8px 0 0 0; color: #888; font-size: 14px;">
            ${frequency === 'daily' ? 'Daily' : 'Weekly'} Digest — ${dateStr}
          </p>
        </div>

        <!-- Articles -->
        <div style="padding: 24px 0;">
          ${categoryHtml || '<p style="color: #888; text-align: center;">No articles for this period.</p>'}
        </div>

        <!-- Footer -->
        <div style="border-top: 1px solid #333; padding-top: 24px; text-align: center; color: #666; font-size: 12px;">
          <p>You received this because you subscribed to Nous AI News.</p>
          <p>
            <a href="{{unsubscribe_url}}" style="color: #8b5cf6;">Unsubscribe</a> •
            <a href="https://nous-daily.vercel.app" style="color: #8b5cf6;">Visit Site</a>
          </p>
        </div>
      </div>
    </body>
    </html>
  `;
}

import { z } from 'zod';
import { NextRequest, NextResponse } from 'next/server';
import { createAdminClient } from '@/lib/supabase/server';
import webpush from 'web-push';

let vapidConfigured = false;

function configureVapidDetails() {
  if (vapidConfigured) return true;

  const publicKey = process.env.VAPID_PUBLIC_KEY;
  const privateKey = process.env.VAPID_PRIVATE_KEY;

  if (!publicKey || !privateKey) {
    return false;
  }

  webpush.setVapidDetails(
    process.env.VAPID_SUBJECT || 'mailto:thasin@live.com',
    publicKey,
    privateKey
  );
  vapidConfigured = true;
  return true;
}

const sendSchema = z.object({
  title: z.string().min(1).max(100),
  body: z.string().min(1).max(200),
  url: z.string().url().default('/'),
  topics: z.array(z.string()).optional(),
  userIds: z.array(z.string().uuid()).optional(),
  icon: z.string().url().optional(),
  badge: z.string().url().optional(),
});

interface PushSubscription {
  endpoint: string;
  p256dh: string;
  auth: string;
  topics: string[];
  user_id: string;
}

async function sendToSubscription(subscription: PushSubscription, payload: object) {
  const pushSubscription = {
    endpoint: subscription.endpoint,
    keys: {
      p256dh: subscription.p256dh,
      auth: subscription.auth,
    },
  };

  try {
    await webpush.sendNotification(pushSubscription, JSON.stringify(payload));
    return { success: true, endpoint: subscription.endpoint };
  } catch (error: any) {
    if (error.statusCode === 410 || error.statusCode === 404) {
      return { success: false, endpoint: subscription.endpoint, reason: 'expired', shouldDelete: true };
    }
    console.error('Push send error:', error);
    return { success: false, endpoint: subscription.endpoint, reason: 'failed' };
  }
}

export async function POST(request: NextRequest) {
  try {
    // Verify internal/cron secret
    const authHeader = request.headers.get('authorization');
    const cronSecret = process.env.CRON_SECRET;
    if (cronSecret && authHeader !== `Bearer ${cronSecret}`) {
      return NextResponse.json({ error: 'Unauthorized' }, { status: 401 });
    }

    const body = await request.json();
    const parsed = sendSchema.safeParse(body);

    if (!parsed.success) {
      return NextResponse.json({ error: 'Invalid request', details: parsed.error.flatten() }, { status: 400 });
    }

    if (!configureVapidDetails()) {
      return NextResponse.json({ error: 'Push notifications are not configured' }, { status: 503 });
    }

    const { title, body: bodyText, url, topics, userIds, icon, badge } = parsed.data;

    const supabase = await createAdminClient();

    // Build query
    let query = supabase.from('push_subscriptions').select('endpoint, p256dh, auth, topics, user_id');

    if (userIds && userIds.length > 0) {
      query = query.in('user_id', userIds);
    }

    const { data: subscriptions, error } = await query;

    if (error) {
      console.error('Fetch subscriptions error:', error);
      return NextResponse.json({ error: 'Failed to fetch subscriptions' }, { status: 500 });
    }

    // Filter by topics if provided
    let filtered = subscriptions || [];
    if (topics && topics.length > 0) {
      filtered = filtered.filter((sub: PushSubscription) =>
        sub.topics && sub.topics.some((t: string) => topics.includes(t))
      );
    }

    // Send notifications in parallel
    const payload = {
      title,
      body: bodyText,
      icon: icon || '/icons/icon-192x192.png',
      badge: badge || '/icons/icon-192x192.png',
      url,
      data: { url },
      actions: [{ action: 'open', title: 'Open' }],
    };

    const results = await Promise.all(
      filtered.map((sub: PushSubscription) => sendToSubscription(sub, payload))
    );

    // Clean up expired subscriptions
    const expiredEndpoints = results
      .filter((r) => r.shouldDelete)
      .map((r) => r.endpoint);

    if (expiredEndpoints.length > 0) {
      await supabase
        .from('push_subscriptions')
        .delete()
        .in('endpoint', expiredEndpoints);
    }

    const successCount = results.filter((r) => r.success).length;

    return NextResponse.json({
      success: true,
      sent: successCount,
      failed: results.length - successCount,
      expiredCleaned: expiredEndpoints.length,
    });
  } catch (error) {
    console.error('Push send API error:', error);
    return NextResponse.json({ error: 'Internal server error' }, { status: 500 });
  }
}

import { NextRequest, NextResponse } from 'next/server';
import { createClient } from '@/lib/supabase/server';

export async function GET(request: NextRequest) {
  try {
    const supabase = await createClient();
    const { data: { user }, error: authError } = await supabase.auth.getUser();

    if (authError || !user) {
      return NextResponse.json({ error: 'Unauthorized' }, { status: 401 });
    }

    const { data: subscription, error } = await supabase
      .from('push_subscriptions')
      .select('*')
      .eq('user_id', user.id)
      .maybeSingle();

    if (error) {
      console.error('Fetch subscription error:', error);
      return NextResponse.json({ error: 'Failed to fetch subscription' }, { status: 500 });
    }

    return NextResponse.json({ subscription });
  } catch (error) {
    console.error('Push subscriptions API error:', error);
    return NextResponse.json({ error: 'Internal server error' }, { status: 500 });
  }
}

import { NextResponse } from 'next/server';
import { SOURCES } from '@/lib/content/sources';
import { fetchRSS, feedItemsToNormalized } from '@/lib/rss/parser';
import { createClient } from '@supabase/supabase-js';
import type { NormalizedArticle } from '@/lib/content/types';

export const dynamic = 'force-dynamic';
export const maxDuration = 60;

// Batch size for concurrent RSS fetches
const FETCH_CONCURRENCY = 20;

/**
 * Fast refresh: fetch 86 RSS sources concurrently, store new articles via upsert.
 * URL-level dedup via onConflict — no pre-fetch of existing articles needed.
 */
export async function POST(request: Request) {
  const url = new URL(request.url);
  const key = url.searchParams.get('key');
  const expectedKey = process.env.REFRESH_KEY || 'nous-ai-news-refresh';
  if (key !== expectedKey) {
    return NextResponse.json({ ok: false, message: 'Unauthorized' }, { status: 401 });
  }

  const startTime = Date.now();
  let totalFetched = 0;
  let totalStored = 0;
  let totalErrors = 0;
  let totalSources = 0;

  // Init Supabase client directly (avoid imports of heavy engine classes)
  const supabaseUrl = process.env.NEXT_PUBLIC_SUPABASE_URL || '';
  const supabaseKey = process.env.SUPABASE_SERVICE_ROLE_KEY || process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY || '';
  if (!supabaseUrl || !supabaseKey) {
    return NextResponse.json({ ok: false, message: 'Missing Supabase credentials' }, { status: 500 });
  }
  const client = createClient(supabaseUrl, supabaseKey, { auth: { persistSession: false } });

  const rssSources = SOURCES.filter((s) => s.active && s.type === 'rss');
  totalSources = rssSources.length;

  // Process in batches of FETCH_CONCURRENCY concurrently
  for (let i = 0; i < rssSources.length; i += FETCH_CONCURRENCY) {
    const batch = rssSources.slice(i, i + FETCH_CONCURRENCY);
    const results = await Promise.allSettled(
      batch.map(async (source) => {
        const feed = await fetchRSS(source.url, 5000);
        if (feed.error || feed.items.length === 0) return 0;
        const articles = feedItemsToNormalized(feed.items, source.id, source.name, 'rss');
        totalFetched += articles.length;

        // Store directly via upsert (URL-level dedup)
        if (articles.length > 0) {
          const dbRows = articles.map((a) => ({
            url: a.url,
            title: a.title,
            summary: a.summary || null,
            content: a.content || null,
            author: a.author || null,
            published_at: a.published_at || null,
            image_url: a.image_url || null,
            source_name: source.name,
            source_type: 'rss' as const,
            source_id: source.id,
            external_id: a.external_id || null,
            language: a.language || 'en',
            category: source.category || 'general',
            tags: a.tags || [],
            score: a.score || 0,
            is_breaking: a.is_breaking || false,
            status: 'published',
          }));

          // eslint-disable-next-line @typescript-eslint/no-explicit-any
          const { error } = await (client.from('articles') as any).upsert(dbRows, {
            onConflict: 'url',
            ignoreDuplicates: true,
          });
          if (!error) totalStored += articles.length;
        }
        return articles.length;
      })
    );

    for (const r of results) {
      if (r.status === 'rejected') totalErrors++;
    }
  }

  // Social signals (HN + Reddit) — lightweight
  try {
    const [hnRes, redditRes] = await Promise.allSettled([
      fetch('https://hacker-news.firebaseio.com/v0/topstories.json', { signal: AbortSignal.timeout(5000) }),
      fetch('https://www.reddit.com/r/artificial/hot.json?limit=5', {
        headers: { 'User-Agent': 'NousAINews/1.0' },
        signal: AbortSignal.timeout(5000),
      }),
    ]);

    if (hnRes.status === 'fulfilled') {
      const ids = await hnRes.value.json() as number[];
      const topIds = ids.slice(0, 10);
      const stories = await Promise.all(
        topIds.map((id) =>
          fetch(`https://hacker-news.firebaseio.com/v0/item/${id}.json`, { signal: AbortSignal.timeout(3000) })
            .then((r) => r.json())
            .catch(() => null)
        )
      );
      const validStories = stories.filter(Boolean).filter((s: any) => s && s.title && s.url);
      if (validStories.length > 0) {
        const hnRows = validStories.map((s: any) => ({
          url: s.url,
          title: s.title,
          summary: s.text || null,
          content: null,
          author: s.by || 'Hacker News',
          published_at: new Date((s.time || 0) * 1000).toISOString(),
          source_name: 'Hacker News',
          source_type: 'social',
          source_id: 'hackernews',
          category: 'community',
          tags: ['hackernews', 'community'],
          score: s.score || 0,
          status: 'published',
        }));
        // eslint-disable-next-line @typescript-eslint/no-explicit-any
        await (client.from('articles') as any).upsert(hnRows, {
          onConflict: 'url',
          ignoreDuplicates: true,
        });
        totalFetched += validStories.length;
        totalStored += validStories.length;
      }
    }
  } catch {
    totalErrors++;
  }

  const durationMs = Date.now() - startTime;

  return NextResponse.json({
    ok: true,
    totalSources,
    totalFetched,
    totalStored,
    totalErrors,
    durationMs,
    message: `Refreshed ${totalSources} sources → ${totalFetched} articles fetched, ${totalStored} stored in ${(durationMs / 1000).toFixed(1)}s`,
  });
}

