'use client';

import { useEffect, useState } from 'react';
import { GitCommit, RefreshCw, CheckCircle2, XCircle, Clock, AlertTriangle, Loader2 } from 'lucide-react';

interface Commit {
  sha: string;
  message: string;
  date: string;
  author: string;
}

interface WorkflowRun {
  name: string;
  status: string;
  conclusion: string | null;
  created_at: string;
  updated_at: string;
  html_url: string;
}

function timeAgo(dateStr: string): string {
  const diff = Date.now() - new Date(dateStr).getTime();
  const mins = Math.floor(diff / 60000);
  if (mins < 60) return `${mins}m ago`;
  const hrs = Math.floor(mins / 60);
  if (hrs < 24) return `${hrs}h ago`;
  const days = Math.floor(hrs / 24);
  return `${days}d ago`;
}

function getStatusIcon(conclusion: string | null, status: string) {
  if (conclusion === 'success') return <CheckCircle2 className="h-3 w-3 text-green-500" />;
  if (conclusion === 'failure') return <XCircle className="h-3 w-3 text-red-500" />;
  if (status === 'in_progress') return <Loader2 className="h-3 w-3 text-primary animate-spin" />;
  if (status === 'queued' || status === 'pending') return <Clock className="h-3 w-3 text-yellow-500" />;
  return <AlertTriangle className="h-3 w-3 text-gray-500" />;
}

function getStatusText(conclusion: string | null, status: string) {
  if (conclusion === 'success') return 'Success';
  if (conclusion === 'failure') return 'Failed';
  if (conclusion === 'cancelled') return 'Cancelled';
  if (conclusion === 'skipped') return 'Skipped';
  if (status === 'in_progress') return 'Running';
  if (status === 'queued' || status === 'pending') return 'Queued';
  return status;
}

function CardWrapper({ title, children }: { title: string; children: React.ReactNode }) {
  return (
    <div className="rounded-xl border border-border/50 bg-card p-4 sm:p-5">
      <h2 className="flex items-center gap-2 text-base font-bold mb-4">
        <GitCommit className="h-4 w-4 text-primary" />
        {title}
      </h2>
      {children}
    </div>
  );
}

export function GitHubStatusClient() {
  const [commits, setCommits] = useState<Commit[]>([]);
  const [workflows, setWorkflows] = useState<WorkflowRun[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    let cancelled = false;

    async function fetchData() {
      try {
        const [commitsRes, workflowsRes] = await Promise.all([
          fetch('https://api.github.com/repos/AtmanTest/nous-ai-news/commits?per_page=5', {
            headers: { Accept: 'application/vnd.github.v3+json' },
          }),
          fetch('https://api.github.com/repos/AtmanTest/nous-ai-news/actions/runs?per_page=5&branch=main', {
            headers: { Accept: 'application/vnd.github.v3+json' },
          }),
        ]);

        if (cancelled) return;

        if (!commitsRes.ok) throw new Error(`GitHub commits: ${commitsRes.status}`);
        if (!workflowsRes.ok) throw new Error(`GitHub workflows: ${workflowsRes.status}`);

        const commitsData = await commitsRes.json();
        const workflowsData = await workflowsRes.json();

        setCommits(
          commitsData.map((c: any) => ({
            sha: c.sha.slice(0, 7),
            message: c.commit.message.split('\n')[0],
            date: c.commit.author?.date || c.commit.committer?.date,
            author: c.commit.author?.name || 'Unknown',
          }))
        );

        setWorkflows(workflowsData.workflow_runs || []);
      } catch (err) {
        if (!cancelled) setError(err instanceof Error ? err.message : 'Failed to load');
      } finally {
        if (!cancelled) setLoading(false);
      }
    }

    fetchData();
    return () => { cancelled = true; };
  }, []);

  if (loading) {
    return (
      <CardWrapper title="GitHub Status">
        <div className="flex items-center justify-center py-8">
          <Loader2 className="h-6 w-6 text-primary animate-spin" />
        </div>
      </CardWrapper>
    );
  }

  if (error) {
    return (
      <CardWrapper title="GitHub Status">
        <div className="text-center py-4 text-sm text-red-500">
          Failed to load GitHub data: {error}
          <br />
          <a href="https://github.com/AtmanTest/nous-ai-news/actions" target="_blank" rel="noopener noreferrer" className="text-primary underline mt-2 inline-block">
            View on GitHub Actions →
          </a>
        </div>
      </CardWrapper>
    );
  }

  return (
    <CardWrapper title="GitHub Status">
      {/* Recent Commits */}
      <div className="space-y-2">
        <h4 className="text-sm font-medium text-muted-foreground">Recent Commits</h4>
        <div className="space-y-1.5 max-h-48 overflow-y-auto">
          {commits.slice(0, 5).map((commit, i) => (
            <div key={i} className="flex items-start gap-2 text-xs p-2 rounded-lg bg-muted/30 hover:bg-muted/50 transition-colors">
              <GitCommit className="h-3 w-3 text-primary mt-0.5 flex-shrink-0" />
              <div className="flex-1 min-w-0">
                <div className="flex items-center gap-2">
                  <code className="font-mono text-primary">{commit.sha}</code>
                  <span className="text-muted-foreground">{timeAgo(commit.date)}</span>
                </div>
                <div className="text-foreground truncate ml-6">{commit.message}</div>
                <div className="text-xs text-muted-foreground ml-6">by {commit.author}</div>
              </div>
            </div>
          ))}
        </div>
      </div>

      {/* Recent Workflow Runs */}
      <div className="mt-4 space-y-2">
        <h4 className="text-sm font-medium text-muted-foreground">Recent Workflow Runs (main)</h4>
        <div className="space-y-1.5 max-h-48 overflow-y-auto">
          {workflows.slice(0, 5).map((run, i) => (
            <div key={i} className="flex items-center justify-between text-xs p-2 rounded-lg bg-muted/30 hover:bg-muted/50 transition-colors">
              <div className="flex items-center gap-2 flex-1 min-w-0">
                <span className="flex-shrink-0">{getStatusIcon(run.conclusion, run.status)}</span>
                <div className="truncate font-mono text-sm">{run.name || 'Unknown workflow'}</div>
              </div>
              <div className="flex items-center gap-2 ml-2 flex-shrink-0">
                <span className={`capitalize text-xs font-medium ${
                  run.conclusion === 'success' ? 'text-green-500' :
                  run.conclusion === 'failure' ? 'text-red-500' :
                  run.status === 'in_progress' ? 'text-primary' :
                  'text-yellow-500'
                }`}>
                  {getStatusText(run.conclusion, run.status)}
                </span>
                <span className="text-muted-foreground whitespace-nowrap">{timeAgo(run.created_at)}</span>
                <a href={run.html_url} target="_blank" rel="noopener noreferrer" className="text-primary hover:underline text-xs flex-shrink-0">
                  View
                </a>
              </div>
            </div>
          ))}
        </div>
      </div>

      <div className="mt-3 pt-2 border-t border-border/30 text-xs text-muted-foreground text-center">
        <a href="https://github.com/AtmanTest/nous-ai-news/actions" target="_blank" rel="noopener noreferrer" className="text-primary underline hover:no-underline">
          Full history on GitHub Actions →
        </a>
      </div>
    </CardWrapper>
  );
}

'use client';

import { useState } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { Mail, Loader2, Check, X, Bell } from 'lucide-react';
import { useTranslations } from 'next-intl';
import { cn } from '@/lib/utils';

interface NewsletterPreferencesProps {}

export function NewsletterPreferences() {
  const t = useTranslations('settings.newsletter');
  const [email, setEmail] = useState('');
  const [frequency, setFrequency] = useState<'daily' | 'weekly'>('daily');
  const [status, setStatus] = useState<'idle' | 'loading' | 'success' | 'error'>('idle');
  const [message, setMessage] = useState('');

  const handleSubscribe = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!email || !email.includes('@')) {
      setStatus('error');
      setMessage(t('invalidEmail'));
      return;
    }

    setStatus('loading');
    setMessage('');

    try {
      const response = await fetch('/api/newsletter/subscribe', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ email, frequency }),
      });

      const data = await response.json();

      if (response.ok) {
        setStatus('success');
        setMessage(t('confirmSent'));
        setEmail('');
      } else {
        setStatus('error');
        setMessage(data.error || t('error'));
      }
    } catch {
      setStatus('error');
      setMessage(t('error'));
    }
  };

  return (
    <SectionCard title={t('title')} icon={Mail}>
      <form onSubmit={handleSubscribe} className="space-y-4">
        <div>
          <label htmlFor="newsletter-email" className="block text-sm font-medium text-muted-foreground mb-1.5">
            {t('emailLabel')}
          </label>
          <input
            id="newsletter-email"
            type="email"
            value={email}
            onChange={(e) => setEmail(e.target.value)}
            placeholder="vous@exemple.com"
            className={cn(
              'w-full px-4 py-2.5 rounded-lg border bg-input/50 text-foreground placeholder:text-muted-foreground/50',
              'focus:outline-none focus:ring-2 focus:ring-primary/50 focus:border-transparent',
              'transition-colors'
            )}
            disabled={status === 'loading'}
          />
        </div>

        <div>
          <label className="block text-sm font-medium text-muted-foreground mb-1.5">
            {t('frequencyLabel')}
          </label>
          <div className="flex gap-3">
            <label className={cn(
              'flex-1 flex items-center justify-center gap-2 px-4 py-2.5 rounded-lg border cursor-pointer transition-colors',
              frequency === 'daily'
                ? 'border-primary/50 bg-primary/10 text-primary'
                : 'border-border/50 bg-card hover:bg-accent/50 text-foreground'
            )}>
              <input
                type="radio"
                name="frequency"
                value="daily"
                checked={frequency === 'daily'}
                onChange={() => setFrequency('daily')}
                className="sr-only"
              />
              {t('daily')}
            </label>
            <label className={cn(
              'flex-1 flex items-center justify-center gap-2 px-4 py-2.5 rounded-lg border cursor-pointer transition-colors',
              frequency === 'weekly'
                ? 'border-primary/50 bg-primary/10 text-primary'
                : 'border-border/50 bg-card hover:bg-accent/50 text-foreground'
            )}>
              <input
                type="radio"
                name="frequency"
                value="weekly"
                checked={frequency === 'weekly'}
                onChange={() => setFrequency('weekly')}
                className="sr-only"
              />
              {t('weekly')}
            </label>
          </div>
        </div>

        <AnimatePresence mode="wait">
          {status !== 'idle' && (
            <motion.div
              initial={{ opacity: 0, y: -10 }}
              animate={{ opacity: 1, y: 0 }}
              exit={{ opacity: 0, y: -10 }}
              className={cn(
                'flex items-center gap-2 px-3 py-2 rounded-lg text-sm',
                status === 'success' ? 'bg-green-500/10 text-green-500' : 'bg-red-500/10 text-red-500'
              )}
            >
              {status === 'success' ? <Check className="h-4 w-4" /> : <X className="h-4 w-4" />}
              <span>{message}</span>
            </motion.div>
          )}
        </AnimatePresence>

        <button
          type="submit"
          disabled={status === 'loading' || !email}
          className={cn(
            'w-full py-2.5 px-4 rounded-lg font-medium transition-all',
            'focus:outline-none focus:ring-2 focus:ring-primary/50',
            status === 'loading' || !email
              ? 'bg-primary/50 text-primary-foreground/50 cursor-not-allowed'
              : 'bg-primary text-primary-foreground hover:opacity-90 active:scale-[0.98]'
          )}
        >
          {status === 'loading' ? (
            <>
              <Loader2 className="h-4 w-4 animate-spin mr-2" />
              {t('subscribing')}
            </>
          ) : (
            t('subscribe')
          )}
        </button>

        <p className="text-xs text-muted-foreground text-center">
          {t('privacy')}
        </p>
      </form>
    </SectionCard>
  );
}

function SectionCard({ title, icon: Icon, children, className = '' }: { title: string; icon: any; children: React.ReactNode; className?: string }) {
  return (
    <div className={cn('rounded-xl border border-border/50 bg-card p-4 sm:p-5', className)}>
      <h2 className="flex items-center gap-2 text-base font-bold mb-4">
        <Icon className="h-4 w-4 text-primary" />
        {title}
      </h2>
      {children}
    </div>
  );
}

'use client';

import { useState } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { Bell, BellOff, Check, X, Loader2 } from 'lucide-react';
import { useTranslations } from 'next-intl';
import { cn } from '@/lib/utils';
import { usePushNotifications } from '@/hooks/usePushNotifications';

interface NotificationPreferencesProps {
  /** Default open state on mobile */
  defaultOpen?: boolean;
}

export function NotificationPreferences({ defaultOpen = false }: NotificationPreferencesProps = {}) {
  const t = useTranslations('push');
  const [isOpen, setIsOpen] = useState(defaultOpen);
  const [pendingTopics, setPendingTopics] = useState<string[]>([]);

  const {
    isSupported,
    permission,
    isSubscribed,
    subscription,
    topics,
    availableTopics,
    loading,
    error,
    subscribe,
    unsubscribe,
    updateTopics,
    requestPermission,
  } = usePushNotifications();

  // Initialize pending topics from current topics
  useState(() => {
    if (subscription?.topics) {
      setPendingTopics(subscription.topics);
    }
  });

  const handleTopicToggle = (topicId: string) => {
    setPendingTopics((prev) =>
      prev.includes(topicId) ? prev.filter((t) => t !== topicId) : [...prev, topicId]
    );
  };

  const handleSubscribe = async () => {
    try {
      await subscribe(pendingTopics);
      setIsOpen(false);
    } catch (err) {
      // Error handled in hook
    }
  };

  const handleUpdateTopics = async () => {
    try {
      await updateTopics(pendingTopics);
      setIsOpen(false);
    } catch (err) {
      // Error handled in hook
    }
  };

  const handleUnsubscribe = async () => {
    try {
      await unsubscribe();
      setPendingTopics([]);
      setIsOpen(false);
    } catch (err) {
      // Error handled in hook
    }
  };

  const handleRequestPermission = async () => {
    await requestPermission();
  };

  if (!isSupported) {
    return (
      <motion.div
        initial={{ opacity: 0, height: 0 }}
        animate={{ opacity: 1, height: 'auto' }}
        className="p-4 rounded-lg bg-amber-50 border border-amber-200"
      >
        <div className="flex items-center gap-3 text-amber-800">
          <BellOff className="h-5 w-5 shrink-0" />
          <p className="text-sm">{t('notSupported')}</p>
        </div>
      </motion.div>
    );
  }

  return (
    <div className="space-y-4">
      {/* Header */}
      <div className="flex items-center justify-between">
        <div className="flex items-center gap-3">
          <div className={cn(
            'p-2 rounded-lg',
            isSubscribed ? 'bg-green-100 text-green-700' : 'bg-gray-100 text-gray-600'
          )}>
            {isSubscribed ? <Bell className="h-5 w-5" /> : <BellOff className="h-5 w-5" />}
          </div>
          <div>
            <h3 className="font-semibold text-foreground">{t('title')}</h3>
            <p className="text-sm text-muted-foreground">
              {isSubscribed ? t('subscribed') : t('notSubscribed')}
            </p>
          </div>
        </div>

        <motion.button
          whileHover={{ scale: 1.02 }}
          whileTap={{ scale: 0.98 }}
          onClick={() => setIsOpen(!isOpen)}
          className={cn(
            'px-3 py-1.5 text-sm font-medium rounded-lg transition-colors',
            isOpen
              ? 'bg-primary text-primary-foreground'
              : 'bg-secondary text-secondary-foreground hover:bg-accent'
          )}
        >
          {isOpen ? t('close') : t('configure')}
        </motion.button>
      </div>

      {/* Content */}
      <AnimatePresence>
        {isOpen && (
          <motion.div
            initial={{ opacity: 0, height: 0 }}
            animate={{ opacity: 1, height: 'auto' }}
            exit={{ opacity: 0, height: 0 }}
            className="space-y-4 p-4 bg-card border border-border rounded-lg"
          >
            {/* Permission status */}
            {permission !== 'granted' && (
              <div className="p-3 rounded-lg bg-amber-50 border border-amber-200">
                <div className="flex items-center justify-between">
                  <div className="flex items-center gap-2 text-amber-800">
                    <BellOff className="h-4 w-4" />
                    <span className="text-sm font-medium">{t('permissionRequired')}</span>
                  </div>
                  <button
                    onClick={handleRequestPermission}
                    disabled={loading}
                    className="px-3 py-1.5 text-sm font-medium text-amber-800 bg-amber-100 rounded-lg hover:bg-amber-200 transition-colors"
                  >
                    {t('enableNotifications')}
                  </button>
                </div>
              </div>
            )}

            {/* Error message */}
            {error && (
              <div className="p-3 rounded-lg bg-red-50 border border-red-200 text-red-800 text-sm">
                {error}
              </div>
            )}

            {/* Topic selection */}
            <div>
              <label className="block text-sm font-medium text-foreground mb-3">
                {t('topicsLabel')}
              </label>
              <p className="text-xs text-muted-foreground mb-3">{t('topicsDescription')}</p>

              <div className="grid gap-2 sm:grid-cols-2">
                {availableTopics.map((topic) => (
                  <motion.button
                    key={topic.id}
                    whileHover={{ scale: 1.01 }}
                    whileTap={{ scale: 0.99 }}
                    onClick={() => handleTopicToggle(topic.id)}
                    className={cn(
                      'flex items-start gap-3 p-3 rounded-lg border-2 transition-all',
                      pendingTopics.includes(topic.id)
                        ? 'border-primary bg-primary/5 text-foreground'
                        : 'border-border bg-background hover:border-primary/50'
                    )}
                    disabled={loading}
                  >
                    <motion.div
                      animate={{ scale: pendingTopics.includes(topic.id) ? 1 : 0.9 }}
                      className={cn(
                        'flex-shrink-0 w-5 h-5 rounded border-2 flex items-center justify-center mt-0.5 transition-colors',
                        pendingTopics.includes(topic.id)
                          ? 'border-primary bg-primary text-primary-foreground'
                          : 'border-border bg-transparent'
                      )}
                    >
                      {pendingTopics.includes(topic.id) && <Check className="h-3 w-3" />}
                    </motion.div>
                    <div className="flex-1 min-w-0">
                      <span className="font-medium text-sm block">{topic.label}</span>
                      <span className="text-xs text-muted-foreground block mt-0.5">{topic.description}</span>
                    </div>
                  </motion.button>
                ))}
              </div>
            </div>

            {/* Actions */}
            <div className="flex gap-3 pt-2 border-t border-border">
              {!isSubscribed ? (
                <motion.button
                  whileHover={{ scale: 1.02 }}
                  whileTap={{ scale: 0.98 }}
                  onClick={handleSubscribe}
                  disabled={loading || pendingTopics.length === 0 || permission !== 'granted'}
                  className="flex-1 px-4 py-2.5 font-medium text-primary-foreground bg-primary rounded-lg hover:opacity-90 transition-opacity disabled:opacity-50 disabled:cursor-not-allowed"
                >
                  {loading ? (
                    <>
                      <Loader2 className="h-4 w-4 mr-2 animate-spin" />
                      {t('subscribing')}
                    </>
                  ) : (
                    t('subscribe')
                  )}
                </motion.button>
              ) : (
                <>
                  <motion.button
                    whileHover={{ scale: 1.02 }}
                    whileTap={{ scale: 0.98 }}
                    onClick={handleUpdateTopics}
                    disabled={loading}
                    className="flex-1 px-4 py-2.5 font-medium text-primary-foreground bg-primary rounded-lg hover:opacity-90 transition-opacity disabled:opacity-50 disabled:cursor-not-allowed"
                  >
                    {loading ? (
                      <>
                        <Loader2 className="h-4 w-4 mr-2 animate-spin" />
                        {t('saving')}
                      </>
                    ) : (
                      t('saveTopics')
                    )}
                  </motion.button>
                  <motion.button
                    whileHover={{ scale: 1.02 }}
                    whileTap={{ scale: 0.98 }}
                    onClick={handleUnsubscribe}
                    disabled={loading}
                    className="px-4 py-2.5 font-medium text-foreground bg-secondary border border-border rounded-lg hover:bg-accent transition-colors disabled:opacity-50 disabled:cursor-not-allowed"
                  >
                    {loading ? (
                      <>
                        <Loader2 className="h-4 w-4 mr-2 animate-spin" />
                        {t('unsubscribing')}
                      </>
                    ) : (
                      t('unsubscribe')
                    )}
                  </motion.button>
                </>
              )}
            </div>

            {/* Current subscription info */}
            {isSubscribed && subscription && (
              <div className="pt-3 text-xs text-muted-foreground">
                <p>{t('subscribedSince', { date: new Date(subscription.created_at).toLocaleDateString() })}</p>
                <p>{t('topicsActive', { count: subscription.topics?.length || 0 })}</p>
              </div>
            )}
          </motion.div>
        )}
      </AnimatePresence>
    </div>
  );
}

export default NotificationPreferences;

'use client';

import { useState, useEffect, useCallback } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { X, Download, Smartphone } from 'lucide-react';
import { useTranslations } from 'next-intl';
import { cn } from '@/lib/utils';

interface BeforeInstallPromptEvent extends Event {
  readonly platforms: string[];
  readonly userChoice: Promise<{
    outcome: 'accepted' | 'dismissed';
    platform: string;
  }>;
  prompt(): Promise<void>;
}

type InstallPromptProps = {
  /** Show only on mobile */
  mobileOnly?: boolean;
  /** Delay before showing prompt (ms) */
  delay?: number;
};

export function PWAInstallPrompt({ mobileOnly = true, delay = 5000 }: InstallPromptProps = {}) {
  const [deferredPrompt, setDeferredPrompt] = useState<BeforeInstallPromptEvent | null>(null);
  const [showPrompt, setShowPrompt] = useState(false);
  const [isInstalled, setIsInstalled] = useState(false);
  const [isBrowser, setIsBrowser] = useState(false);
  const t = useTranslations('pwa.install');

  // Mark as browser environment
  useEffect(() => {
    setIsBrowser(true);
  }, []);

  // Check if app is already installed (standalone mode)
  useEffect(() => {
    if (!isBrowser) return;
    const isStandalone = window.matchMedia('(display-mode: standalone)').matches;
    const isIOSStandalone = (window.navigator as any).standalone === true;
    setIsInstalled(isStandalone || isIOSStandalone);
  }, [isBrowser]);

  // Listen for beforeinstallprompt event
  useEffect(() => {
    if (!isBrowser) return;
    const handler = (e: Event) => {
      e.preventDefault();
      setDeferredPrompt(e as BeforeInstallPromptEvent);
    };

    window.addEventListener('beforeinstallprompt', handler);
    return () => window.removeEventListener('beforeinstallprompt', handler);
  }, [isBrowser]);

  // Show prompt after delay if conditions met
  useEffect(() => {
    if (!isBrowser || isInstalled || deferredPrompt === null) return;

    const timer = setTimeout(() => {
      if (!mobileOnly || /Android|iPhone|iPad|iPod/i.test(navigator.userAgent)) {
        setShowPrompt(true);
      }
    }, delay);

    return () => clearTimeout(timer);
  }, [isBrowser, isInstalled, deferredPrompt, mobileOnly, delay]);

  const handleInstall = useCallback(async () => {
    if (!deferredPrompt) return;

    deferredPrompt.prompt();
    const { outcome } = await deferredPrompt.userChoice;
    console.log('PWA install outcome:', outcome);
    setDeferredPrompt(null);
    setShowPrompt(false);
    if (outcome === 'accepted') {
      setIsInstalled(true);
    }
  }, [deferredPrompt]);

  const handleDismiss = useCallback(() => {
    setShowPrompt(false);
    // Don't show again for 24h
    localStorage.setItem('pwa-install-dismissed', Date.now().toString());
  }, []);

  // Don't show if dismissed recently
  useEffect(() => {
    if (!isBrowser) return;
    const dismissed = localStorage.getItem('pwa-install-dismissed');
    if (dismissed && Date.now() - parseInt(dismissed) < 24 * 60 * 60 * 1000) {
      setShowPrompt(false);
    }
  }, [isBrowser]);

  if (!isBrowser || isInstalled || !showPrompt || !deferredPrompt) {
    return null;
  }

  return (
    <AnimatePresence>
      <motion.div
        initial={{ opacity: 0, y: 20, scale: 0.95 }}
        animate={{ opacity: 1, y: 0, scale: 1 }}
        exit={{ opacity: 0, y: -20, scale: 0.95 }}
        className={cn(
          'fixed bottom-4 left-4 right-4 md:left-auto md:bottom-4 md:right-4 md:w-96 z-50',
          'bg-card border border-border rounded-xl shadow-xl p-4',
          'backdrop-blur-sm bg-background/95'
        )}
        role="dialog"
        aria-live="polite"
      >
        <div className="flex items-start gap-3">
          <div className="flex-shrink-0 p-2 rounded-lg bg-primary/10 text-primary">
            <Smartphone className="h-5 w-5" />
          </div>

          <div className="flex-1 min-w-0">
            <h3 className="font-semibold text-foreground">{t('title')}</h3>
            <p className="text-sm text-muted-foreground mt-1">{t('description')}</p>
            <p className="text-xs text-muted-foreground mt-2">{t('benefits')}</p>
          </div>

          <div className="flex items-center gap-2">
            <motion.button
              whileHover={{ scale: 1.05 }}
              whileTap={{ scale: 0.95 }}
              onClick={handleInstall}
              className="flex items-center gap-1.5 px-3 py-2 text-sm font-medium text-primary-foreground bg-primary rounded-lg hover:opacity-90 transition-opacity"
            >
              <Download className="h-4 w-4" />
              {t('install')}
            </motion.button>
            <button
              onClick={handleDismiss}
              className="p-2 rounded-lg text-muted-foreground hover:bg-accent hover:text-accent-foreground transition-colors"
              aria-label={t('dismiss')}
            >
              <X className="h-4 w-4" />
            </button>
          </div>
        </div>
      </motion.div>
    </AnimatePresence>
  );
}

export default PWAInstallPrompt;

