              <div className="flex items-center gap-2 text-[11px] text-muted-foreground">
                {published_at && <span suppressHydrationWarning>{timeAgo(published_at)}</span>}
                <span>·</span>
                <span>{minutes}m read</span>
              </div>

            </div>
          </div>
        </div>
      </Link>
    );
