        'group block rounded-xl border border-border/40 bg-card overflow-hidden transition-all duration-300',
        'hover:border-primary/20 hover:shadow-sm hover:-translate-y-0.5',
        is_featured && 'sm:col-span-2 sm:row-span-2',
