            {score && score > 70 && (
              <span className={cn(
                'inline-flex items-center gap-0.5 text-[10px] font-semibold px-1.5 py-0.5 rounded',
                is_featured ? 'bg-black/60 text-white' : 'bg-primary/10 text-primary'
