'use client';

import { createContext, useContext, useState, useCallback, useEffect, useRef, ReactNode } from 'react';

interface Article {
  id: string;
  title: string;
  summary: string | null;
  image_url: string | null;
  source_name: string;
  source_logo?: string;
  source_handle?: string;
  category: string | null;
  tags: string[];
  published_at: string;
  score: number;
  is_breaking: boolean;
}

interface NewsContextType {
  articles: Article[];
  isLoading: boolean;
  hasMore: boolean;
  error: string | null;
  activeTab: string;
  setActiveTab: (tab: string) => void;
  loadMore: () => Promise<void>;
  refresh: () => Promise<void>;
}

const NewsContext = createContext<NewsContextType | null>(null);

const PAGE_SIZE = 20;

export function NewsProvider({ children, initialArticles = [] }: { children: ReactNode; initialArticles?: Article[] }) {
  const [articles, setArticles] = useState<Article[]>(initialArticles);
  const [isLoading, setIsLoading] = useState(false);
  const [hasMore, setHasMore] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [activeTab, setActiveTab] = useState('for-you');
  const cursorRef = useRef<string | null>(null);

  const loadMore = useCallback(async () => {
    if (isLoading || !hasMore) return;
    setIsLoading(true);
    setError(null);

    try {
      const params = new URLSearchParams({
        tab: activeTab,
        limit: String(PAGE_SIZE),
      });
      if (cursorRef.current) params.set('cursor', cursorRef.current);

      const res = await fetch(`/api/news?${params}`);
      if (!res.ok) throw new Error('Failed to fetch');

      const data = await res.json();
      setArticles(prev => [...prev, ...data.articles]);
      cursorRef.current = data.next_cursor || null;
      setHasMore(data.has_more);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Unknown error');
    } finally {
      setIsLoading(false);
    }
  }, [isLoading, hasMore, activeTab]);

  const refresh = useCallback(async () => {
    cursorRef.current = null;
    setArticles([]);
    setHasMore(true);
    await loadMore();
  }, [loadMore]);

  return (
    <NewsContext.Provider value={{ articles, isLoading, hasMore, error, activeTab, setActiveTab, loadMore, refresh }}>
      {children}
    </NewsContext.Provider>
  );
}

export function useNews() {
  const ctx = useContext(NewsContext);
  if (!ctx) throw new Error('useNews must be used within NewsProvider');
  return ctx;
}

'use client';

import { useState, useEffect, useCallback, useRef } from 'react';

interface UseArticleCountsByDayReturn {
  counts: Record<string, number>;
  isLoading: boolean;
  error: string | null;
  refresh: () => Promise<void>;
}

const CACHE_DURATION = 5 * 60 * 1000; // 5 minutes
let memoryCache: { data: Record<string, number>; timestamp: number } | null = null;

// Export for testing
export const _resetMemoryCache = () => {
  memoryCache = null;
};

export function useArticleCountsByDay(days: number = 7): UseArticleCountsByDayReturn {
  const [counts, setCounts] = useState<Record<string, number>>({});
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const mountedRef = useRef(true);

  useEffect(() => {
    mountedRef.current = true;
    return () => { mountedRef.current = false; };
  }, []);

  const fetchCounts = useCallback(async () => {
    if (!mountedRef.current) return;

    // Check memory cache first
    if (memoryCache && Date.now() - memoryCache.timestamp < CACHE_DURATION) {
      if (mountedRef.current) {
        setCounts(memoryCache.data);
        setIsLoading(false);
      }
      return;
    }

    setIsLoading(true);
    setError(null);

    try {
      const params = new URLSearchParams({ days: String(days) });
      const res = await fetch(`/api/news/counts-by-day?${params}`);

      if (!res.ok) throw new Error('Failed to fetch counts');

      const data = await res.json();

      if (!mountedRef.current) return;

      const newCounts = data.counts || {};
      memoryCache = { data: newCounts, timestamp: Date.now() };
      setCounts(newCounts);
    } catch (err) {
      if (!mountedRef.current) return;
      setError(err instanceof Error ? err.message : 'An error occurred');
      // On error, return empty counts rather than crashing
      if (Object.keys(counts).length === 0) {
        setCounts({});
      }
    } finally {
      if (mountedRef.current) {
        setIsLoading(false);
      }
    }
  }, [days]);

  useEffect(() => {
    fetchCounts();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [days]);

  const refresh = useCallback(async () => {
    memoryCache = null; // Invalidate cache
    await fetchCounts();
  }, [fetchCounts]);

  return {
    counts,
    isLoading,
    error,
    refresh,
  };
}

'use client';

import { useState, useCallback, useEffect, useRef } from 'react';
import { useRouter, usePathname } from 'next/navigation';

export interface DailyArticle {
  id: string;
  title: string;
  summary: string | null;
  image_url: string | null;
  source_name: string;
  category: string | null;
  tags: string[];
  published_at: string;
  score: number;
  is_breaking: boolean;
}

export interface DailyDay {
  date: string; // YYYY-MM-DD
  label: string; // "Today", "Yesterday", "Monday June 8"
  articles: DailyArticle[];
}

export interface UseDailyFeedReturn {
  days: DailyDay[];
  isLoading: boolean;
  isLoadingMore: boolean;
  hasMore: boolean;
  error: string | null;
  loadMore: () => Promise<void>;
  refresh: () => Promise<void>;
}

const DEFAULT_LIMIT = 50;

export function useDailyFeed(): UseDailyFeedReturn {
  const router = useRouter();
  const pathname = usePathname();

  const [days, setDays] = useState<DailyDay[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [isLoadingMore, setIsLoadingMore] = useState(false);
  const [hasMore, setHasMore] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const cursorRef = useRef<string | null>(null);
  const mountedRef = useRef(true);

  useEffect(() => {
    mountedRef.current = true;
    return () => { mountedRef.current = false; };
  }, []);

  const fetchFeed = useCallback(async (append: boolean) => {
    if (!mountedRef.current) return;

    if (append) {
      setIsLoadingMore(true);
    } else {
      setIsLoading(true);
    }
    setError(null);

    try {
      const params = new URLSearchParams({
        limit: String(DEFAULT_LIMIT),
      });
      if (append && cursorRef.current) {
        params.set('cursor', cursorRef.current);
      }

      const res = await fetch(`/api/daily-feed?${params}`);
      if (!res.ok) throw new Error('Failed to fetch daily feed');

      const data = await res.json();

      if (!mountedRef.current) return;

      if (append) {
        setDays(prev => [...prev, ...data.days]);
      } else {
        setDays(data.days);
      }
      cursorRef.current = data.nextCursor || null;
      setHasMore(data.hasMore);
    } catch (err) {
      if (!mountedRef.current) return;
      setError(err instanceof Error ? err.message : 'An error occurred');
    } finally {
      if (mountedRef.current) {
        setIsLoading(false);
        setIsLoadingMore(false);
      }
    }
  }, []);

  // Initial fetch
  useEffect(() => {
    fetchFeed(false);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  const loadMore = useCallback(async () => {
    if (isLoadingMore || !hasMore || isLoading) return;
    await fetchFeed(true);
  }, [fetchFeed, isLoadingMore, hasMore, isLoading]);

  const refresh = useCallback(async () => {
    cursorRef.current = null;
    setDays([]);
    setHasMore(true);
    await fetchFeed(false);
  }, [fetchFeed]);

  return {
    days,
    isLoading,
    isLoadingMore,
    hasMore,
    error,
    loadMore,
    refresh,
  };
}

'use client';

import { useState, useCallback, useEffect, useRef } from 'react';
import { useRouter, usePathname, useSearchParams } from 'next/navigation';

export interface ForYouArticle {
  id: string;
  title: string;
  summary: string | null;
  url: string;
  source_name: string;
  source_type: string;
  source_tier: number | null;
  category: string | null;
  published_at: string;
  score: number;
  base_score: number | null;
  social_momentum: number | null;
  detected_models: string[] | null;
  image_url: string | null;
  slug: string;
  relevance_score: number;
  reason: string;
}

export interface ForYouResponse {
  articles: ForYouArticle[];
  next_cursor: string | null;
  has_more: boolean;
  personalized: boolean;
}

interface UseForYouFeedOptions {
  limit?: number;
  hoursBack?: number;
}

export function useForYouFeed(options: UseForYouFeedOptions = {}) {
  const { limit = 20, hoursBack = 168 } = options;
  const router = useRouter();
  const pathname = usePathname();
  const searchParams = useSearchParams();

  const [articles, setArticles] = useState<ForYouArticle[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [isLoadingMore, setIsLoadingMore] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [hasMore, setHasMore] = useState(true);
  const [personalized, setPersonalized] = useState(false);
  const [nextCursor, setNextCursor] = useState<string | null>(null);
  const loadingRef = useRef(false);

  const buildUrl = useCallback((cursor?: string) => {
    const params = new URLSearchParams();
    params.set('limit', limit.toString());
    params.set('hours_back', hoursBack.toString());
    if (cursor) params.set('cursor', cursor);
    return `/api/for-you?${params.toString()}`;
  }, [limit, hoursBack]);

  const fetchFeed = useCallback(async (cursor?: string, isLoadMore = false) => {
    if (loadingRef.current) return;
    loadingRef.current = true;

    try {
      if (isLoadMore) {
        setIsLoadingMore(true);
      } else {
        setIsLoading(true);
        setError(null);
      }

      const response = await fetch(buildUrl(cursor));

      if (!response.ok) {
        throw new Error(`HTTP ${response.status}`);
      }

      const data: ForYouResponse = await response.json();

      if (isLoadMore) {
        setArticles((prev) => [...prev, ...data.articles]);
      } else {
        setArticles(data.articles);
      }

      setHasMore(data.has_more);
      setNextCursor(data.next_cursor);
      setPersonalized(data.personalized);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Failed to load feed');
    } finally {
      setIsLoading(false);
      setIsLoadingMore(false);
      loadingRef.current = false;
    }
  }, [buildUrl]);

  const refresh = useCallback(() => {
    setNextCursor(null);
    fetchFeed();
  }, [fetchFeed]);

  const loadMore = useCallback(() => {
    if (nextCursor && hasMore && !isLoadingMore) {
      fetchFeed(nextCursor, true);
    }
  }, [nextCursor, hasMore, isLoadingMore, fetchFeed]);

  // Initial load
  useEffect(() => {
    fetchFeed();
  }, [fetchFeed]);

  return {
    articles,
    isLoading,
    isLoadingMore,
    error,
    hasMore,
    personalized,
    refresh,
    loadMore,
  };
}

export function useForYouInfiniteScroll(
  loadMore: () => void,
  hasMore: boolean,
  isLoadingMore: boolean
) {
  const observerRef = useRef<IntersectionObserver | null>(null);
  const triggerRef = useRef<HTMLDivElement | null>(null);

  useEffect(() => {
    if (observerRef.current) {
      observerRef.current.disconnect();
    }

    observerRef.current = new IntersectionObserver(
      (entries) => {
        const target = entries[0];
        if (target.isIntersecting && hasMore && !isLoadingMore) {
          loadMore();
        }
      },
      { rootMargin: '200px', threshold: 0.1 }
    );

    if (triggerRef.current) {
      observerRef.current.observe(triggerRef.current);
    }

    return () => {
      if (observerRef.current) {
        observerRef.current.disconnect();
      }
    };
  }, [loadMore, hasMore, isLoadingMore]);

  return triggerRef;
}

'use client';

import { useEffect, useRef, useState, useCallback } from 'react';
import { useTranslations } from 'next-intl';
import { motion, AnimatePresence } from 'framer-motion';
import { Loader2, RefreshCw, X } from 'lucide-react';
import { cn } from '@/lib/utils';

interface SSEMessage {
  type: 'connected' | 'heartbeat' | 'new-articles';
  count?: number;
  timestamp: number;
}

export function useLiveUpdates(onNewArticles?: (count: number) => void) {
  const [isConnected, setIsConnected] = useState(false);
  const [newArticlesCount, setNewArticlesCount] = useState(0);
  const [error, setError] = useState<string | null>(null);
  const eventSourceRef = useRef<EventSource | null>(null);
  const reconnectTimeoutRef = useRef<NodeJS.Timeout | null>(null);
  const reconnectAttempts = useRef(0);
  const maxReconnectAttempts = 5;
  const t = useTranslations('liveUpdates');

  const connect = useCallback(() => {
    if (eventSourceRef.current) {
      eventSourceRef.current.close();
    }

    const es = new EventSource('/api/events');
    eventSourceRef.current = es;

    es.onopen = () => {
      setIsConnected(true);
      setError(null);
      reconnectAttempts.current = 0;
    };

    es.onmessage = (event) => {
      try {
        const data: SSEMessage = JSON.parse(event.data);

        switch (data.type) {
          case 'connected':
            setIsConnected(true);
            break;
          case 'heartbeat':
            // Keep alive
            break;
          case 'new-articles':
            if (data.count && data.count > 0) {
              setNewArticlesCount(data.count);
              onNewArticles?.(data.count);
            }
            break;
        }
      } catch {
        // Ignore parse errors
      }
    };

    es.onerror = () => {
      setIsConnected(false);
      setError(t('connectionError'));

      es.close();

      // Exponential backoff reconnect
      if (reconnectAttempts.current < maxReconnectAttempts) {
        const delay = Math.min(1000 * Math.pow(2, reconnectAttempts.current), 30000);
        reconnectTimeoutRef.current = setTimeout(() => {
          reconnectAttempts.current++;
          connect();
        }, delay);
      } else {
        setError(t('maxRetriesReached'));
      }
    };
  }, [onNewArticles, t]);

  const dismiss = useCallback(() => {
    setNewArticlesCount(0);
  }, []);

  const reconnect = useCallback(() => {
    reconnectAttempts.current = 0;
    connect();
  }, [connect]);

  useEffect(() => {
    connect();
    return () => {
      if (eventSourceRef.current) {
        eventSourceRef.current.close();
      }
      if (reconnectTimeoutRef.current) {
        clearTimeout(reconnectTimeoutRef.current);
      }
    };
  }, [connect]);

  return {
    isConnected,
    newArticlesCount,
    error,
    dismiss,
    reconnect,
  };
}

// ── Live Updates Badge Component ────────────────────────────────────────────

export function LiveUpdatesBadge() {
  const { isConnected, newArticlesCount, error, dismiss, reconnect } = useLiveUpdates();
  const t = useTranslations('liveUpdates');

  if (!newArticlesCount && !error) return null;

  return (
    <AnimatePresence mode="wait">
      {error && (
        <motion.div
          initial={{ opacity: 0, y: -20 }}
          animate={{ opacity: 1, y: 0 }}
          exit={{ opacity: 0, y: -20 }}
          className="fixed top-20 left-1/2 -translate-x-1/2 z-50"
        >
          <div className="flex items-center gap-2 px-4 py-2 bg-destructive/90 text-destructive-foreground rounded-lg shadow-lg backdrop-blur-sm border border-destructive/20">
            <Loader2 className="h-4 w-4 animate-spin" />
            <span className="text-sm font-medium">{t('reconnecting')}</span>
            <button onClick={reconnect} className="text-xs underline hover:no-underline">{t('retry')}</button>
          </div>
        </motion.div>
      )}

      {newArticlesCount > 0 && (
        <motion.div
          initial={{ opacity: 0, y: -20, scale: 0.95 }}
          animate={{ opacity: 1, y: 0, scale: 1 }}
          exit={{ opacity: 0, y: -20, scale: 0.95 }}
          className="fixed top-20 left-1/2 -translate-x-1/2 z-50"
        >
          <div className="flex items-center gap-2 px-4 py-2 bg-primary/95 text-primary-foreground rounded-lg shadow-lg backdrop-blur-sm border border-primary/20">
            <RefreshCw className="h-4 w-4 animate-spin" />
            <span className="text-sm font-medium">
              {t('newArticles', { count: newArticlesCount })}
            </span>
            <button
              onClick={() => window.location.reload()}
              className="px-2 py-1 text-xs bg-primary-foreground/20 rounded hover:bg-primary-foreground/30"
            >
              {t('refresh')}
            </button>
            <button onClick={dismiss} className="text-lg leading-none hover:opacity-70">
              <X className="h-4 w-4" />
            </button>
          </div>
        </motion.div>
      )}
    </AnimatePresence>
  );
}

'use client';

import { useState, useCallback, useEffect } from 'react';
import { useAuth } from '@/contexts/AuthContext';
import { useTranslations } from 'next-intl';
import { cn } from '@/lib/utils';

interface PushSubscription {
  endpoint: string;
  keys: {
    p256dh: string;
    auth: string;
  };
}

interface PushSubscriptionData {
  id: number;
  user_id: string;
  endpoint: string;
  p256dh: string;
  auth: string;
  topics: string[];
  user_agent: string | null;
  created_at: string;
  updated_at: string;
}

interface UsePushNotificationsReturn {
  isSupported: boolean;
  permission: NotificationPermission;
  isSubscribed: boolean;
  subscription: PushSubscriptionData | null;
  topics: string[];
  availableTopics: { id: string; label: string; description: string }[];
  loading: boolean;
  error: string | null;
  subscribe: (topics?: string[]) => Promise<void>;
  unsubscribe: () => Promise<void>;
  updateTopics: (topics: string[]) => Promise<void>;
  requestPermission: () => Promise<NotificationPermission>;
}

const TOPIC_OPTIONS = [
  { id: 'trending', label: 'Trending Articles', description: 'Most popular articles right now' },
  { id: 'breaking', label: 'Breaking News', description: 'Major announcements as they happen' },
  { id: 'models', label: 'New Models', description: 'New LLM releases and updates' },
  { id: 'research', label: 'Research Papers', description: 'New papers and breakthroughs' },
  { id: 'business', label: 'Business & Funding', description: 'Funding rounds, acquisitions, IPOs' },
  { id: 'policy', label: 'Policy & Regulation', description: 'AI regulation and government actions' },
] as const;

export function usePushNotifications(): UsePushNotificationsReturn {
  const { user } = useAuth();
  const t = useTranslations('push');
  const [isSupported, setIsSupported] = useState(false);
  const [permission, setPermission] = useState<NotificationPermission>('default');
  const [isSubscribed, setIsSubscribed] = useState(false);
  const [subscription, setSubscription] = useState<PushSubscriptionData | null>(null);
  const [topics, setTopics] = useState<string[]>([]);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const availableTopics = TOPIC_OPTIONS.map((opt) => ({
    id: opt.id,
    label: t(`topics.${opt.id}.label`, { defaultValue: opt.label }),
    description: t(`topics.${opt.id}.description`, { defaultValue: opt.description }),
  }));

  // Check support and permission on mount
  useEffect(() => {
    const supported = 'serviceWorker' in navigator && 'PushManager' in window;
    setIsSupported(supported);

    if (supported) {
      setPermission(Notification.permission);
    }
  }, []);

  // Fetch existing subscription for current user
  useEffect(() => {
    if (!user || !isSupported) return;

    const fetchSubscription = async () => {
      try {
        const response = await fetch('/api/push/subscriptions');
        if (response.ok) {
          const data = await response.json();
          if (data.subscription) {
            setSubscription(data.subscription);
            setIsSubscribed(true);
            setTopics(data.subscription.topics || []);
          }
        }
      } catch (err) {
        console.error('Failed to fetch push subscription:', err);
      }
    };

    fetchSubscription();
  }, [user, isSupported]);

  const requestPermission = useCallback(async () => {
    if (!isSupported) return 'denied';

    try {
      const perm = await Notification.requestPermission();
      setPermission(perm);
      return perm;
    } catch (err) {
      console.error('Permission request failed:', err);
      return 'denied';
    }
  }, [isSupported]);

  const getVapidPublicKey = useCallback(async () => {
    const response = await fetch('/api/push/vapid-public-key');
    if (!response.ok) throw new Error('Failed to get VAPID key');
    const { publicKey } = await response.json();
    return publicKey;
  }, []);

  const urlBase64ToUint8Array = useCallback((base64String: string) => {
    const padding = '='.repeat((4 - (base64String.length % 4)) % 4);
    const base64 = (base64String + padding).replace(/-/g, '+').replace(/_/g, '/');
    const rawData = window.atob(base64);
    const outputArray = new Uint8Array(rawData.length);
    for (let i = 0; i < rawData.length; ++i) {
      outputArray[i] = rawData.charCodeAt(i);
    }
    return outputArray;
  }, []);

  const subscribe = useCallback(async (selectedTopics: string[] = []) => {
    if (!user || !isSupported) {
      setError(t('errors.notSupported'));
      return;
    }

    if (permission !== 'granted') {
      const perm = await requestPermission();
      if (perm !== 'granted') {
        setError(t('errors.permissionDenied'));
        return;
      }
    }

    setLoading(true);
    setError(null);

    try {
      // Register service worker if not already
      const registration = await navigator.serviceWorker.ready;

      // Get VAPID key
      const vapidPublicKey = await getVapidPublicKey();
      const applicationServerKey = urlBase64ToUint8Array(vapidPublicKey);

      // Subscribe
      const pushSubscription = await registration.pushManager.subscribe({
        userVisibleOnly: true,
        applicationServerKey,
      });

      const subscriptionJson = pushSubscription.toJSON() as PushSubscription;

      // Send to backend
      const response = await fetch('/api/push/subscribe', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          endpoint: subscriptionJson.endpoint,
          keys: {
            p256dh: subscriptionJson.keys?.p256dh || '',
            auth: subscriptionJson.keys?.auth || '',
          },
          topics: selectedTopics,
          userAgent: navigator.userAgent,
        }),
      });

      if (!response.ok) {
        const err = await response.json();
        throw new Error(err.error || 'Subscription failed');
      }

      const { subscription: savedSub } = await response.json();
      setSubscription(savedSub);
      setIsSubscribed(true);
      setTopics(savedSub.topics || []);
    } catch (err: any) {
      console.error('Push subscribe error:', err);
      setError(err.message || t('errors.subscribeFailed'));
      throw err;
    } finally {
      setLoading(false);
    }
  }, [user, isSupported, permission, requestPermission, getVapidPublicKey, urlBase64ToUint8Array, t]);

  const unsubscribe = useCallback(async () => {
    if (!subscription) return;

    setLoading(true);
    setError(null);

    try {
      // Unregister from browser
      const registration = await navigator.serviceWorker.ready;
      const pushSubscription = await registration.pushManager.getSubscription();
      if (pushSubscription) {
        await pushSubscription.unsubscribe();
      }

      // Notify backend
      const response = await fetch('/api/push/unsubscribe', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ endpoint: subscription.endpoint }),
      });

      if (!response.ok) {
        throw new Error('Unsubscribe failed');
      }

      setSubscription(null);
      setIsSubscribed(false);
      setTopics([]);
    } catch (err: any) {
      console.error('Push unsubscribe error:', err);
      setError(err.message || t('errors.unsubscribeFailed'));
      throw err;
    } finally {
      setLoading(false);
    }
  }, [subscription, t]);

  const updateTopics = useCallback(async (newTopics: string[]) => {
    if (!subscription) return;

    setLoading(true);
    setError(null);

    try {
      // Re-subscribe with new topics
      const registration = await navigator.serviceWorker.ready;
      const pushSubscription = await registration.pushManager.getSubscription();
      if (!pushSubscription) throw new Error('No subscription found');

      const subscriptionJson = pushSubscription.toJSON() as PushSubscription;

      const response = await fetch('/api/push/subscribe', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          endpoint: subscriptionJson.endpoint,
          keys: {
            p256dh: subscriptionJson.keys?.p256dh || '',
            auth: subscriptionJson.keys?.auth || '',
          },
          topics: newTopics,
          userAgent: navigator.userAgent,
        }),
      });

      if (!response.ok) {
        throw new Error('Update topics failed');
      }

      const { subscription: savedSub } = await response.json();
      setSubscription(savedSub);
      setTopics(savedSub.topics || []);
    } catch (err: any) {
      console.error('Update topics error:', err);
      setError(err.message || t('errors.updateFailed'));
      throw err;
    } finally {
      setLoading(false);
    }
  }, [subscription, t]);

  return {
    isSupported,
    permission,
    isSubscribed,
    subscription,
    topics,
    availableTopics,
    loading,
    error,
    subscribe,
    unsubscribe,
    updateTopics,
    requestPermission,
  };
}

export default usePushNotifications;

/**
 * Cache Manager — high-level cache wrapper.
 *
 * Provides tiered caching for API routes with:
 * - Automatic Redis → memory → stale fallback
 * - Configurable TTL per namespace
 * - Tag-based invalidation
 * - Performance metrics
 */

import { cache } from './redis';

// ─── Types ────────────────────────────────────────────────────────────────────

export interface CacheConfig {
  /** Time-to-live in milliseconds (default: 5 min) */
  ttlMs: number;
  /** Namespace prefix for cache keys */
  namespace: string;
  /** Whether to serve stale data when refresh fails (default: true) */
  serveStale?: boolean;
}

export interface CachedResponse<T> {
  data: T;
  cached: boolean;
  stale?: boolean;
  source: 'redis' | 'memory' | 'fresh';
  timing?: number;
}

export interface CacheMetrics {
  hits: number;
  misses: number;
  memorySize: number;
  mode: 'redis' | 'memory';
}

// ─── Default configs per namespace ─────────────────────────────────────────────

const DEFAULT_CONFIGS: Record<string, CacheConfig> = {
  trending: { ttlMs: 5 * 60 * 1000, namespace: 'trending', serveStale: true },
  'for-you': { ttlMs: 3 * 60 * 1000, namespace: 'for-you', serveStale: true },
  latest: { ttlMs: 60 * 1000, namespace: 'latest', serveStale: true },
  'huggingface-trending': { ttlMs: 15 * 60 * 1000, namespace: 'huggingface-trending', serveStale: true },
  article: { ttlMs: 10 * 60 * 1000, namespace: 'article', serveStale: false },
};

const STALE_MARKER = '__stale__';

function buildKey(namespace: string, ...parts: string[]): string {
  return ['daily-ai', namespace, ...parts].join(':');
}

// ─── Stale store (last known good data) ────────────────────────────────────────

const staleStore = new Map<string, { data: unknown; timestamp: number }>();

// ─── Public API ────────────────────────────────────────────────────────────────

export const cacheManager = {
  /**
   * Fetch data with caching. Tries cache first, then factory, falls back to stale.
   *
   * @example
   * ```ts
   * const result = await cacheManager.fetch('trending', ['page-1'], () => fetchTrending(), { ttlMs: 300_000 });
   * ```
   */
  async fetch<T>(
    namespace: string,
    keyParts: string[],
    factory: () => Promise<T>,
    config?: Partial<CacheConfig>,
  ): Promise<CachedResponse<T>> {
    const defaults = DEFAULT_CONFIGS[namespace];
    const cfg: CacheConfig = {
      ...(defaults || { namespace }),
      ...config,
      // Always respect the explicitly passed namespace
      namespace: config?.namespace || defaults?.namespace || namespace,
    };
    const cacheKey = buildKey(cfg.namespace, ...keyParts);
    const staleKey = buildKey(cfg.namespace, 'stale', ...keyParts);
    const start = performance.now();

    // 1. Try primary cache
    const cached = await cache.get<T>(cacheKey);
    if (cached !== null) {
      const timing = Math.round(performance.now() - start);
      return { data: cached, cached: true, source: 'redis', timing };
    }

    // 2. Try stale store
    const stale = staleStore.get(staleKey) as { data: T; timestamp: number } | undefined;
    if (stale && cfg.serveStale !== false) {
      const timing = Math.round(performance.now() - start);
      return { data: stale.data, cached: true, stale: true, source: 'memory', timing };
    }

    // 3. Fetch fresh data
    try {
      const data = await factory();
      const timing = Math.round(performance.now() - start);

      // Cache the result
      await cache.set(cacheKey, data, cfg.ttlMs);

      // Save to stale store
      staleStore.set(staleKey, { data: data as unknown, timestamp: Date.now() });

      return { data, cached: false, source: 'fresh', timing };
    } catch (err) {
      // 4. Factory failed — try stale again (in case it was just checked)
      const staleRetry = staleStore.get(staleKey) as { data: T; timestamp: number } | undefined;
      if (staleRetry && cfg.serveStale !== false) {
        const timing = Math.round(performance.now() - start);
        return { data: staleRetry.data, cached: true, stale: true, source: 'memory', timing };
      }

      throw err;
    }
  },

  /**
   * Invalidate cached data for a namespace and optional key parts.
   */
  async invalidate(namespace: string, ...keyParts: string[]): Promise<void> {
    const cacheKey = buildKey(namespace, ...keyParts);
    await cache.del(cacheKey);

    // Also clear stale
    const staleKey = buildKey(namespace, 'stale', ...keyParts);
    staleStore.delete(staleKey);
  },

  /**
   * Invalidate all cached data for a namespace.
   */
  async invalidateNamespace(namespace: string): Promise<void> {
    // Clear matching entries from stale store
    const prefix = buildKey(namespace, 'stale');
    for (const key of staleStore.keys()) {
      if (key.startsWith(prefix)) {
        staleStore.delete(key);
      }
    }
    // Note: full namespace invalidation would require scanning Redis keys.
    // For now, this clears the stale store — the next fetch will get fresh data.
  },

  /**
   * Get cache metrics.
   */
  getMetrics(): CacheMetrics {
    const s = cache.stats();
    return {
      hits: s.hits,
      misses: s.misses,
      memorySize: s.size,
      mode: s.mode,
    };
  },

  /**
   * Clear all caches.
   */
  async clear(): Promise<void> {
    staleStore.clear();
    cache.clear();
  },
};

