const CACHE_NAME = 'nous-ai-news-v1';
const SHELL_CACHE = 'nous-ai-news-shell-v1';
const FEED_CACHE = 'nous-ai-news-feed-v1';
const ASSET_CACHE = 'nous-ai-news-assets-v1';

const SHELL_URLS = [
  '/',
  '/feed',
  '/trending',
  '/search',
  '/offline'
];

const ASSET_EXTENSIONS = [
  '.js', '.css', '.json', '.ico', '.png', '.jpg', '.jpeg',
  '.webp', '.svg', '.woff', '.woff2', '.ttf', '.eot'
];

// Install: cache the app shell
self.addEventListener('install', (event) => {
  event.waitUntil(
    (async () => {
      const shellCache = await caches.open(SHELL_CACHE);
      await shellCache.addAll(SHELL_URLS);
      // Pre-cache the offline page
      const offlineResponse = await fetch('/offline');
      if (offlineResponse.ok) {
        await shellCache.put('/offline', offlineResponse);
      }
      // Skip waiting so the new SW activates immediately
      self.skipWaiting();
    })()
  );
});

// Activate: clean up old caches
self.addEventListener('activate', (event) => {
  event.waitUntil(
    (async () => {
      const cacheNames = await caches.keys();
      const validCaches = [CACHE_NAME, SHELL_CACHE, FEED_CACHE, ASSET_CACHE];
      await Promise.all(
        cacheNames
          .filter((name) => !validCaches.includes(name))
          .map((name) => caches.delete(name))
      );
      // Claim all clients so the SW controls pages immediately
      await self.clients.claim();
    })()
  );
});

// Helper: is this a navigation request?
function isNavigationRequest(request) {
  return request.mode === 'navigate' ||
    (request.method === 'GET' &&
      request.headers.get('Accept')?.includes('text/html'));
}

// Helper: is this an asset request?
function isAssetRequest(url) {
  const pathname = new URL(url).pathname;
  return ASSET_EXTENSIONS.some((ext) => pathname.endsWith(ext)) ||
    pathname.startsWith('/_next/static/') ||
    pathname.startsWith('/fonts/');
}

// Helper: is this an API request?
function isApiRequest(url) {
  const pathname = new URL(url).pathname;
  return pathname.startsWith('/api/');
}

// Strategy: Network First with fallback to cache (for navigations and feed)
async function networkFirst(request, cacheName) {
  try {
    const networkResponse = await fetch(request);
    if (networkResponse.ok) {
      const cache = await caches.open(cacheName || CACHE_NAME);
      const clonedResponse = networkResponse.clone();
      // Don't cache opaque responses (cross-origin)
      if (clonedResponse.type === 'basic' || clonedResponse.type === 'cors') {
        cache.put(request, clonedResponse);
      }
    }
    return networkResponse;
  } catch (error) {
    const cachedResponse = await caches.match(request);
    if (cachedResponse) {
      return cachedResponse;
    }
    // If it's a navigation request, show the offline page
    if (isNavigationRequest(request)) {
      const offlineCache = await caches.open(SHELL_CACHE);
      const offlinePage = await offlineCache.match('/offline');
      if (offlinePage) {
        return offlinePage;
      }
    }
    throw error;
  }
}

// Strategy: Cache First with network update (for assets)
async function cacheFirst(request, cacheName) {
  const cache = await caches.open(cacheName || ASSET_CACHE);
  const cachedResponse = await cache.match(request);
  if (cachedResponse) {
    // Update cache in background
    fetch(request).then((networkResponse) => {
      if (networkResponse.ok) {
        cache.put(request, networkResponse);
      }
    }).catch(() => {});
    return cachedResponse;
  }
  try {
    const networkResponse = await fetch(request);
    if (networkResponse.ok) {
      cache.put(request, networkResponse.clone());
    }
    return networkResponse;
  } catch (error) {
    throw error;
  }
}

// Strategy: Stale While Revalidate (for shell pages)
async function staleWhileRevalidate(request, cacheName) {
  const cache = await caches.open(cacheName || SHELL_CACHE);
  const cachedResponse = await cache.match(request);
  const fetchPromise = fetch(request).then((networkResponse) => {
    if (networkResponse.ok) {
      cache.put(request, networkResponse.clone());
    }
    return networkResponse;
  }).catch((error) => {
    // If fetch fails and we have a cached response, return it
    if (cachedResponse) {
      return cachedResponse;
    }
    throw error;
  });
  // Return cached response immediately if available, otherwise wait for network
  return cachedResponse || fetchPromise;
}

// Fetch: route requests to appropriate strategy
self.addEventListener('fetch', (event) => {
  const { request } = event;
  const url = new URL(request.url);

  // Only handle same-origin requests
  if (url.origin !== self.location.origin) return;

  // Skip API requests (don't cache them)
  if (isApiRequest(url)) return;

  // Skip non-GET requests
  if (request.method !== 'GET') return;

  // Asset requests: cache first
  if (isAssetRequest(url)) {
    event.respondWith(cacheFirst(request, ASSET_CACHE));
    return;
  }

  // Navigation requests: network first, fallback to offline page
  if (isNavigationRequest(request)) {
    event.respondWith(networkFirst(request, SHELL_CACHE));
    return;
  }

  // Feed-related pages: network first with dedicated cache
  const pathname = url.pathname;
  if (pathname === '/' || pathname.startsWith('/feed') || pathname.startsWith('/trending')) {
    event.respondWith(networkFirst(request, FEED_CACHE));
    return;
  }

  // Everything else: network first
  event.respondWith(networkFirst(request));
});

// Push event handler
self.addEventListener('push', (event) => {
  if (!event.data) return;

  let data;
  try {
    data = event.data.json();
  } catch {
    data = { title: 'Nous AI News', body: event.data.text() };
  }

  const title = data.title || 'Nous AI News';
  const options = {
    body: data.body || '',
    icon: '/icons/icon-192x192.png',
    badge: '/icons/icon-192x192.png',
    vibrate: [200, 100, 200],
    data: {
      url: data.url || '/',
      dateOfArrival: Date.now()
    },
    actions: [
      { action: 'open', title: 'Open' }
    ]
  };

  event.waitUntil(
    self.registration.showNotification(title, options)
  );
});

// Notification click handler
self.addEventListener('notificationclick', (event) => {
  event.notification.close();

  const urlToOpen = event.notification.data?.url || '/';

  event.waitUntil(
    clients.matchAll({ type: 'window', includeUncontrolled: true }).then((windowClients) => {
      // If a window is already open, focus it and navigate
      for (const client of windowClients) {
        if (client.url === urlToOpen && 'focus' in client) {
          return client.focus();
        }
      }
      // Otherwise open a new window
      if (clients.openWindow) {
        return clients.openWindow(urlToOpen);
      }
    })
  );
});

const fs = require('fs');
const path = require('path');
const { execSync } = require('child_process');

const REPORT_DIR = path.join(__dirname, '..', 'reports');
const LLM_API_KEY = process.env.LLM_API_KEY || '';
const LLM_API_URL = process.env.LLM_API_URL || 'https://integrate.api.nvidia.com/v1/chat/completions';
const LLM_MODEL = process.env.LLM_MODEL || 'mistralai/mistral-nemotron';

function ensureDir(dir) { if (!fs.existsSync(dir)) fs.mkdirSync(dir, { recursive: true }); }

async function callLLM(prompt, systemPrompt = 'Return only valid JSON.') {
  if (!LLM_API_KEY) return null;
  try {
    const res = await fetch(LLM_API_URL, {
      method: 'POST',
      headers: {
        'Authorization': `Bearer ${LLM_API_KEY}`,
        'Content-Type': 'application/json',
      },
      body: JSON.stringify({
        model: LLM_MODEL,
        messages: [
          { role: 'system', content: systemPrompt },
          { role: 'user', content: prompt }
        ],
        temperature: 0.1,
        max_tokens: 2000,
      }),
    });
    const data = await res.json();
    const text = data?.choices?.[0]?.message?.content || '';
    const match = text.match(/\[[\s\S]*?\]/);
    return match ? JSON.parse(match[0]) : null;
  } catch (e) {
    console.error('  LLM call failed:', e.message);
    return null;
  }
}

async function main() {
  console.log('🐛 Bug Fixer — scanning issues...');
  ensureDir(REPORT_DIR);

  const fixes = [];

  // 1. Read ESLint report
  try {
    const eslintReport = JSON.parse(fs.readFileSync(path.join(REPORT_DIR, 'eslint-report.json'), 'utf8'));
    const errors = [];
    Object.entries(eslintReport).forEach(([file, msgs]) => {
      msgs.forEach((m) => {
        if (m.severity === 2) errors.push({ file, line: m.line, message: m.message, rule: m.ruleId });
      });
    });

    if (errors.length > 0) {
      // Ask LLM for auto-fix suggestions for the first 5 errors
      const topErrors = errors.slice(0, 5);
      const prompt = `Suggest an ESLint auto-fix for each error (ONLY if trivial/mechanical). Return JSON array:\n[{"file": "...", "line": N, "fix": "exact text to replace the line with" or null if risky}]\n\nErrors:\n${topErrors.map((e) => `${e.file}:${e.line} — ${e.message} (${e.rule})`).join('\n')}`;

      const suggestedFixes = await callLLM(prompt, 'Return only valid JSON. Return null for risky/ambiguous fixes.');
      if (suggestedFixes) {
        suggestedFixes.forEach((f) => {
          if (f.fix && f.file && f.line) {
            try {
              const fullPath = path.join(__dirname, '..', f.file);
              if (fs.existsSync(fullPath)) {
                const content = fs.readFileSync(fullPath, 'utf8').split('\n');
                const idx = f.line - 1;
                if (idx >= 0 && idx < content.length) {
                  content[idx] = f.fix;
                  fs.writeFileSync(fullPath, content.join('\n'));
                  fixes.push({ file: f.file, line: f.line, fix: f.fix });
                }
              }
            } catch (e) {
              console.error(`  ✗ Failed to fix ${f.file}:${f.line} — ${e.message}`);
            }
          }
        });
      }
    }
  } catch (e) {
    console.error('  No ESLint report or parse error:', e.message);
  }

  // 2. Quick auto-fixes for common patterns
  const ignorePatterns = ['@typescript-eslint/no-explicit-any', '@next/next/no-img-element'];
  const commentedFiles = {};

  try {
    const eslintReport = JSON.parse(fs.readFileSync(path.join(REPORT_DIR, 'eslint-report.json'), 'utf8'));
    Object.entries(eslintReport).forEach(([file, msgs]) => {
      msgs.forEach((m) => {
        if (ignorePatterns.includes(m.ruleId)) {
          if (!commentedFiles[file]) commentedFiles[file] = new Set();
          commentedFiles[file].add(m.ruleId);
        }
      });
    });
  } catch {}

  // Add eslint-disable comments for known patterns
  Object.entries(commentedFiles).forEach(([relFile, rules]) => {
    const fullPath = path.join(__dirname, '..', relFile);
    if (!fs.existsSync(fullPath)) return;
    const content = fs.readFileSync(fullPath, 'utf8');
    // Only add if not already there
    rules.forEach((rule) => {
      const comment = `/* eslint-disable ${rule} */`;
      if (!content.includes(comment)) {
        const lines = content.split('\n');
        // Find a good insertion point (after imports)
        let insertIdx = 0;
        for (let i = 0; i < lines.length; i++) {
          if (lines[i].startsWith('import ')) insertIdx = i + 1;
        }
        if (insertIdx < lines.length) {
          lines.splice(insertIdx, 0, comment);
          fs.writeFileSync(fullPath, lines.join('\n'));
          fixes.push({ file: relFile, action: `added ${comment}` });
        }
      }
    });
  });

  // 3. Save fix report
  if (fixes.length > 0) {
    fs.writeFileSync(path.join(REPORT_DIR, 'auto-fixes.json'), JSON.stringify({ timestamp: new Date().toISOString(), fixes }, null, 2));
    console.log(`✅ Applied ${fixes.length} auto-fixes`);
  } else {
    console.log('  No auto-fixes applied');
  }
}

main().catch(console.error);

import { getActiveSources } from '../../lib/content/sources';
import { fetchRSS } from '../../lib/rss/parser';
import type { NormalizedArticle } from '../../lib/content/types';

/**
 * Fetch articles from all active RSS/news sources
 */
export async function fetchAllSources(): Promise<NormalizedArticle[]> {
  const sources = getActiveSources();
  const results: NormalizedArticle[] = [];
  const errors: string[] = [];

  for (const source of sources) {
    try {
      if (source.type === 'rss') {
        const feed = await fetchRSS(source.url);
        if (feed.error) {
          errors.push(`${source.name}: ${feed.error}`);
          continue;
        }
        // Convert feed items
        for (const item of feed.items) {
          results.push({
            url: item.link,
            title: item.title,
            summary: item.description || null,
            content: item.content || null,
            author: item.author || null,
            published_at: item.pubDate || null,
            image_url: item.image || null,
            source_name: source.name,
            source_type: 'rss',
            source_id: source.id,
            external_id: null,
            language: source.language,
            category: null,
            tags: item.categories || [],
            entities: [],
            score: 0,
            is_breaking: false,
          });
        }
      }
    } catch (err) {
      errors.push(`${source.name}: fetch error`);
    }
  }

  if (errors.length > 0) {
    console.warn(`[NewsFetch] ${errors.length} source(s) had errors`);
    errors.forEach((e) => console.warn(`  ⚠ ${e}`));
  }

  return results;
}

/**
 * AI News Shield — Main Cycle
 * Runs every 4 hours: fetch → normalize → dedupe → rank → enrich → publish → revalidate → health → report
 */
import { fetchAllSources } from './news-fetch';
import { fetchAllSocialSignals } from './signals-fetch';
import { batchDeduplicate } from '../../lib/content/dedupe';
import { calculateScore, calculateTrendingScore } from '../../lib/content/rank';
import { enrichArticle } from '../../lib/content/enrich';
import { storeArticles, fetchExistingArticles, logIngestion } from '../../lib/content/store';
import { checkSiteHealth } from './health-check';
import { revalidateSite } from './revalidate';
import { generateShieldReport } from './report';

interface ShieldRunResult {
  startedAt: string;
  endedAt: string;
  status: 'success' | 'partial' | 'failed';
  articlesAdded: number;
  articlesUpdated: number;
  duplicatesRemoved: number;
  brokenSources: number;
  signalsFetched: number;
  healthScore: number;
  errors: string[];
  appliedImprovements: string[];
}

async function main() {
  const startedAt = new Date().toISOString();
  const errors: string[] = [];
  const improvements: string[] = [];
  let articlesAdded = 0;
  let articlesUpdated = 0;
  let duplicatesRemoved = 0;
  let brokenSources = 0;
  let signalsFetched = 0;
  let healthScore = 0;

  console.log(`[Shield] ════════════════════════════════════`);
  console.log(`[Shield] 🛡️  Shield Cycle Started: ${startedAt}`);
  console.log(`[Shield] ════════════════════════════════════`);

  try {
    // Step 1: Fetch news
    console.log(`\n[Shield] 1/7 📡 Fetching news sources...`);
    const newsArticles = await fetchAllSources();
    console.log(`[Shield] Fetched ${newsArticles.length} raw articles`);

    // Step 2: Fetch social signals
    console.log(`\n[Shield] 2/7 🔥 Fetching social signals...`);
    const signals = await fetchAllSocialSignals();
    signalsFetched = signals.length;
    console.log(`[Shield] Fetched ${signals.length} social signals`);

    // Step 3: Normalize
    console.log(`\n[Shield] 3/7 🔄 Normalizing content...`);
    // (normalization happens inside processArticles)

    // Step 4: Deduplicate
    console.log(`\n[Shield] 4/7 🔍 Deduplicating...`);
    const existing = await fetchExistingArticles();
    const { newArticles, duplicates } = batchDeduplicate(newsArticles, existing);
    duplicatesRemoved = duplicates.length;
    console.log(`[Shield] ${newArticles.length} new, ${duplicates.length} duplicates`);

    // Step 5: Rank
    console.log(`\n[Shield] 5/7 📊 Ranking...`);
    const ranked = newArticles.map((a) => ({
      ...a,
      score: calculateScore(a, 2),
      trending_score: calculateTrendingScore(a, 2),
    }));

    // Step 6: Enrich
    console.log(`\n[Shield] 6/7 ✨ Enriching entities...`);
    const enriched = ranked.map(enrichArticle);

    // Step 7: Store
    console.log(`\n[Shield] 7/7 💾 Storing articles...`);
    const storeResult = await storeArticles(enriched);
    articlesAdded = storeResult.stored;

    // Revalidate cache
    console.log(`\n[Shield] Revalidating site cache...`);
    await revalidateSite();

    // Health check
    console.log(`\n[Shield] Running health check...`);
    const health = await checkSiteHealth();
    healthScore = health.score;

    if (health.errors.length > 0) {
      errors.push(...health.errors);
    }

    if (storeResult.errors > 0) {
      errors.push(`${storeResult.errors} store errors`);
    }

  } catch (err) {
    const msg = err instanceof Error ? err.message : 'Unknown shield error';
    errors.push(msg);
    console.error(`[Shield] ❌ Fatal: ${msg}`);
  }

  const endedAt = new Date().toISOString();
  const status = errors.length === 0 ? 'success' : errors.length > 3 ? 'failed' : 'partial';

  const result: ShieldRunResult = {
    startedAt,
    endedAt,
    status,
    articlesAdded,
    articlesUpdated,
    duplicatesRemoved,
    brokenSources,
    signalsFetched,
    healthScore,
    errors,
    appliedImprovements: improvements,
  };

  // Generate report
  await generateShieldReport(result);

  console.log(`\n[Shield] ════════════════════════════════════`);
  console.log(`[Shield] ✅ Done: ${articlesAdded} added, ${duplicatesRemoved} dup, ${errors.length} err`);
  console.log(`[Shield] Status: ${status} | Duration: ${(Date.now() - new Date(startedAt).getTime()) / 1000}s`);
  console.log(`[Shield] ════════════════════════════════════`);

  process.exit(errors.length > 3 ? 1 : 0);
}

main().catch((err) => {
  console.error('[Shield] Fatal:', err);
  process.exit(1);
});

