    // freshnessMultiplier(72) = 0.5^(72/12) = 0.5^6 = 1/64 ≈ 0.015625
    const fm = Math.pow(0.5, 6);
    const freshnessContribution = fm * 100 * 0.3;
    // base=6, social=10, source=16, model=3, freshness≈0.46875
